const lessons = [
{"num": 2, "time": "00:00:30,000 --> 00:00:32,000", "arabic": "تَعَالِي تَعَالِي، أَعْطِينِي هَذِي.", "segs": null, "full_uz": "Kel, kel, buni menga ber.", "note": null},
{"num": 3, "time": "00:00:35,500 --> 00:00:41,000", "arabic": "تَأَخَّرْتُمْ، أَسْرِعِي يَا أُمَّ سَلَمَةَ، فَالْمَرْأَةُ تُوشِكُ أَنْ تَلْفِظَ أَنْفَاسَهَا، أَسْرِعِي.", "segs": [{"ar": "تَأَخَّرْتُمْ، أَسْرِعِي يَا أُمَّ سَلَمَةَ،", "uz": "Kechikdinglar, tezroq bo'ling, ey Umm Salama,"}, {"ar": "فَالْمَرْأَةُ تُوشِكُ أَنْ تَلْفِظَ أَنْفَاسَهَا، أَسْرِعِي.", "uz": "ayol jon berish arafasida, tezroq bo'ling."}], "full_uz": "Kechikdinglar, tezroq bo'ling, ey Umm Salama, ayol jon berish arafasida, tezroq bo'ling.", "note": null},
{"num": 5, "time": "00:00:41,000 --> 00:00:43,000", "arabic": "إِلَى أَيْنَ؟", "segs": null, "full_uz": "Qayoqqa?", "note": null},
{"num": 6, "time": "00:00:43,000 --> 00:00:46,000", "arabic": "هَاتِهَا، ابْقَ خَارِجًا رَيْثَمَا، أَنْتَ.", "segs": null, "full_uz": "Buni ber, sen esa hozircha tashqarida turib tur.", "note": null},
{"num": 7, "time": "00:01:00,000 --> 00:01:08,780", "arabic": "خُذِي وَاشْرَبِيهِ مِنْ هَذَا الْمَاءِ.", "segs": null, "full_uz": "Ol, mana bu suvdan ich.", "note": null},
{"num": 8, "time": "00:01:08,780 --> 00:01:19,460", "arabic": "أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يُعَافِيَكِ وَيَشْفِيَكِ.", "segs": null, "full_uz": "Buyuk arshning Robbi bo'lgan Ulug' Allohdan senga ofiyat va shifo berishini so'rayman.", "note": null},
{"num": 10, "time": "00:01:19,460 --> 00:01:22,900", "arabic": "فِي ذَاتِ نَفْسِي يَا عَبَّاسَةُ.", "segs": null, "full_uz": "Ichimda xavotirdaman, ey Abbasa.", "note": null},
{"num": 11, "time": "00:01:22,900 --> 00:01:25,219", "arabic": "أَنْتِ بِخَيْرٍ إِنْ شَاءَ اللَّهُ.", "segs": null, "full_uz": "Sen sog'-omonsan, inshaalloh.", "note": null},
{"num": 12, "time": "00:01:25,219 --> 00:01:30,799", "arabic": "إِنِّي أَرَاكِ بِخَيْرٍ إِنْ شَاءَ اللَّهُ يَا عَبَّاسَةُ.", "segs": null, "full_uz": "Seni sog'-omon ko'ryapman, inshaalloh, ey Abbasa.", "note": null},
{"num": 13, "time": "00:01:30,799 --> 00:01:47,579", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 14, "time": "00:01:47,579 --> 00:01:49,539", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 15, "time": "00:01:49,540 --> 00:01:56,040", "arabic": "أَطَرَدْتَنِي أَنْتَ أَيْضًا يَا عُمَرُ؟", "segs": null, "full_uz": "Meni sen ham quvib chiqarganmiding, Umar?", "note": null},
{"num": 16, "time": "00:01:56,040 --> 00:02:00,200", "arabic": "يَا لَهَا مِنِ امْرَأَةٍ قَاسِيَةِ الْقَلْبِ! تَخَيَّلْ.", "segs": null, "full_uz": "Naqadar qattiq qalbli ayol! Tasavvur qil.", "note": null},
{"num": 18, "time": "00:02:00,200 --> 00:02:06,960", "arabic": "لَمْ تَدَعْنِي فِي غُرْفَتِي مُغْلِقًا الْبَابَ عَلَى نَفْسِي، قَالَتْ لِي: اذْهَبْ يَا عُمَرُ، اذْهَبْ.", "segs": [{"ar": "لَمْ تَدَعْنِي فِي غُرْفَتِي مُغْلِقًا الْبَابَ عَلَى نَفْسِي،", "uz": "Meni xonamda eshikni yopib o'tirishimga ham qo'ymadi,"}, {"ar": "قَالَتْ لِي: اذْهَبْ يَا عُمَرُ، اذْهَبْ.", "uz": "menga: \"Ket, Umar, ket\" dedi."}], "full_uz": "Meni xonamda eshikni yopib o'tirishimga ham qo'ymadi, menga: \"Ket, Umar, ket\" dedi.", "note": null},
{"num": 20, "time": "00:02:06,960 --> 00:02:10,620", "arabic": "إِنَّهَا كَأَبِيهَا الْجَزَّارِ، لَا تَعْرِفُ إِلَّا تَكْسِيرَ الْعِظَامِ.", "segs": null, "full_uz": "U qassob otasiga o'xshaydi, faqat suyak sindirishni biladi.", "note": null},
{"num": 22, "time": "00:02:10,620 --> 00:02:17,460", "arabic": "إِنَّهُ صَبِيٌّ صَحِيحٌ مُعَافًى يَا وَلَدِي، بَارَكَ اللَّهُ لَكَ فِيهِ.", "segs": [{"ar": "إِنَّهُ صَبِيٌّ صَحِيحٌ مُعَافًى يَا وَلَدِي،", "uz": "U sog'lom, tuzuk bolakay, o'g'lim,"}, {"ar": "بَارَكَ اللَّهُ لَكَ فِيهِ.", "uz": "Alloh senga uni muborak qilsin."}], "full_uz": "U sog'lom, tuzuk bolakay, o'g'lim, Alloh senga uni muborak qilsin.", "note": null},
{"num": 24, "time": "00:02:17,460 --> 00:02:19,180", "arabic": "وَمَاذَا عَنْ سُعَادَ؟", "segs": null, "full_uz": "Su'odning ahvoli qalay?", "note": null},
{"num": 25, "time": "00:02:19,180 --> 00:02:23,780", "arabic": "إِنَّهَا بِخَيْرٍ وَالْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ عَلَى كُلِّ شَيْءٍ.", "segs": null, "full_uz": "U sog'-omon, alhamdulillah, hamma narsa uchun hamd Allohga xosdir.", "note": null},
{"num": 27, "time": "00:02:23,780 --> 00:02:27,379", "arabic": "مُبَارَكٌ يَا عُمَرُ مُبَارَكٌ، سَلَامَةٌ سَلَامَةٌ.", "segs": null, "full_uz": "Muborak bo'lsin, Umar, muborak bo'lsin, omonlik, omonlik.", "note": null},
{"num": 28, "time": "00:02:27,379 --> 00:02:34,060", "arabic": "إِيهِ! إِلَى أَيْنَ؟ إِلَى أَيْنَ؟ هَذَا لَيْسَ دُكَّانًا أَيُّهَا الْإِسْكَافِيُّ.", "segs": [{"ar": "إِيهِ! إِلَى أَيْنَ؟ إِلَى أَيْنَ؟", "uz": "Hey! Qayoqqa? Qayoqqa?"}, {"ar": "هَذَا لَيْسَ دُكَّانًا أَيُّهَا الْإِسْكَافِيُّ.", "uz": "Bu do'kon emas, ey etikdo'z!"}], "full_uz": "Hey! Qayoqqa? Qayoqqa? Bu do'kon emas, ey etikdo'z!", "note": null},
{"num": 29, "time": "00:02:34,060 --> 00:02:35,780", "arabic": "أُرِيدُ أَنْ أَرَى حَفِيدِي فِي حِجْرِي.", "segs": null, "full_uz": "Nabiramni quchog'imda ko'rmoqchiman.", "note": null},
{"num": 30, "time": "00:02:35,780 --> 00:02:39,680", "arabic": "هَلْ عَرَفْتَ أَيُّهَا الرَّجُلُ؟ الْمَرْأَةُ نَفْسُهَا فِي الدَّاخِلِ.", "segs": null, "full_uz": "Tushundingmi, odam bolasi? Ayolning o'zi ichkarida.", "note": null},
{"num": 31, "time": "00:02:39,680 --> 00:03:02,640", "arabic": "تَمَهَّلْ تَمَهَّلْ، لَقَدْ نَسِيتُ، قُمْ عُدْ إِلَى زَوْجِكَ وَعِيَالِكَ يَا وَلَدِي.", "segs": [{"ar": "تَمَهَّلْ تَمَهَّلْ، لَقَدْ نَسِيتُ،", "uz": "Shoshma, shoshma, unutib qo'yibman,"}, {"ar": "قُمْ عُدْ إِلَى زَوْجِكَ وَعِيَالِكَ يَا وَلَدِي.", "uz": "tur, xotining va bolalaring oldiga qayt, o'g'lim."}], "full_uz": "Shoshma, shoshma, unutib qo'yibman, tur, xotining va bolalaring oldiga qayt, o'g'lim.", "note": null},
{"num": 33, "time": "00:03:02,640 --> 00:03:04,879", "arabic": "أُمُّكَ نَائِمَةٌ الْآنَ.", "segs": null, "full_uz": "Onang hozir uxlab yotibdi.", "note": null},
{"num": 34, "time": "00:03:04,879 --> 00:03:09,520", "arabic": "وَا لَهْفَ نَفْسِي عَلَى أُمِّي يَا أَبِي!", "segs": null, "full_uz": "Voy, onamga achinaman-a, dadajon!", "note": null},
{"num": 35, "time": "00:03:09,520 --> 00:03:12,700", "arabic": "أَعَجَزَ الْأَطِبَّاءُ أَنْ يَجِدُوا لَهَا عِلَاجًا؟", "segs": null, "full_uz": "Tabiblar unga davo topa olmay qolishdimi?", "note": null},
{"num": 36, "time": "00:03:12,700 --> 00:03:14,819", "arabic": "اللَّهُ وَحْدَهُ الشَّافِي يَا وَلَدِي.", "segs": null, "full_uz": "Shifo beruvchi yolg'iz Allohdir, o'g'lim.", "note": null},
{"num": 37, "time": "00:03:14,819 --> 00:03:24,659", "arabic": "أَخْبَرَنِي الْأَطِبَّاءُ أَنَّ مَرَضَهَا مَرَضٌ عُضَالٌ، وَلَكِنَّ الْمَوْتَ وَالْحَيَاةَ بِيَدِ اللَّهِ عَزَّ وَجَلَّ.", "segs": [{"ar": "أَخْبَرَنِي الْأَطِبَّاءُ أَنَّ مَرَضَهَا مَرَضٌ عُضَالٌ،", "uz": "Tabiblar menga uning kasali davolab bo'lmas kasal ekanini aytishdi,"}, {"ar": "وَلَكِنَّ الْمَوْتَ وَالْحَيَاةَ بِيَدِ اللَّهِ عَزَّ وَجَلَّ.", "uz": "lekin o'lim va hayot Alloh azza va jallaning qo'lidadir."}], "full_uz": "Tabiblar menga uning kasali davolab bo'lmas kasal ekanini aytishdi, lekin o'lim va hayot Alloh azza va jallaning qo'lidadir.", "note": null},
{"num": 40, "time": "00:03:24,659 --> 00:03:32,099", "arabic": "وَا أَسَفِي عَلَى نَفْسِي يَا أُمِّي، وَا أَسَفِي.", "segs": null, "full_uz": "Voy holimga, onajon, voy holimga.", "note": null},
{"num": 42, "time": "00:03:32,099 --> 00:03:32,899", "arabic": "يَا وَلَدِي.", "segs": null, "full_uz": "O'g'lim.", "note": null},
{"num": 43, "time": "00:03:32,899 --> 00:03:48,099", "arabic": "لَا أُرِيدُ أَنْ أَرَاكَ ضَعِيفًا هَكَذَا، أَنْتَ رَجُلٌ مُؤْمِنٌ، وَتَعْلَمُ أَنَّ الْمَوْتَ عَلَى الْعِبَادِ حَقٌّ، وَأَنَّ الصَّبْرَ عِنْدَ الصَّدْمَةِ الْأُولَى، فَلَا تَفْقِدْ إِيمَانَكَ لِأَمْرٍ تَعْلَمُ أَنَّهُ قَدَرٌ.", "segs": [{"ar": "لَا أُرِيدُ أَنْ أَرَاكَ ضَعِيفًا هَكَذَا،", "uz": "Seni bunday ojiz holda ko'rishni istamayman,"}, {"ar": "أَنْتَ رَجُلٌ مُؤْمِنٌ،", "uz": "sen mo'min erkaksan,"}, {"ar": "وَتَعْلَمُ أَنَّ الْمَوْتَ عَلَى الْعِبَادِ حَقٌّ،", "uz": "o'limning bandalar uchun haq ekanini va"}, {"ar": "وَأَنَّ الصَّبْرَ عِنْدَ الصَّدْمَةِ الْأُولَى،", "uz": "sabr birinchi zarba paytida bo'lishini"}, {"ar": "فَلَا تَفْقِدْ إِيمَانَكَ لِأَمْرٍ تَعْلَمُ أَنَّهُ قَدَرٌ.", "uz": "bilasan. Taqdir ekanini bilgan narsa uchun imoningni yo'qotma."}], "full_uz": "Seni bunday ojiz holda ko'rishni istamayman, sen mo'min erkaksan, o'limning bandalar uchun haq ekanini va sabr birinchi zarba paytida bo'lishini bilasan. Taqdir ekanini bilgan narsa uchun imoningni yo'qotma.", "note": "\"الصبر عند الصدمة الأولى\" — Payg'ambar (sav)ning hadisiga ishora (Buxoriy, Muslim)."},
{"num": 48, "time": "00:03:53,099 --> 00:03:57,099", "arabic": "لَا اعْتِرَاضَ عَلَى حُكْمِ اللَّهِ يَا أَبِي.", "segs": null, "full_uz": "Allohning hukmiga e'tiroz yo'q, dadajon.", "note": null},
{"num": 50, "time": "00:03:58,099 --> 00:04:06,099", "arabic": "لَكِنَّهَا أُمِّي، لَيْسَ لِي فِي الدُّنْيَا سِوَاهَا، لَيْتَنِي أَسْتَطِيعُ فِدَاءَهَا بِنَفْسِي، لَيْتَ كُلَّ مَا أَصَابَهَا كَانَ بِي.", "segs": [{"ar": "لَكِنَّهَا أُمِّي، لَيْسَ لِي فِي الدُّنْيَا سِوَاهَا،", "uz": "Lekin u mening onam, dunyoda mendan boshqa hech kimim yo'q. Qani edi,"}, {"ar": "لَيْتَنِي أَسْتَطِيعُ فِدَاءَهَا بِنَفْسِي،", "uz": "o'zimni unga fido qila olsam. Qani edi,"}, {"ar": "لَيْتَ كُلَّ مَا أَصَابَهَا كَانَ بِي.", "uz": "unga yetgan hamma narsa menga yetganida."}], "full_uz": "Lekin u mening onam, dunyoda mendan boshqa hech kimim yo'q. Qani edi, o'zimni unga fido qila olsam. Qani edi, unga yetgan hamma narsa menga yetganida.", "note": null},
{"num": 54, "time": "00:04:08,099 --> 00:04:10,099", "arabic": "إِنَّهَا صَالِحَةٌ يَا أَبِي.", "segs": null, "full_uz": "U solihadir, dadajon.", "note": null},
{"num": 55, "time": "00:04:14,099 --> 00:04:23,819", "arabic": "لَا بَأْسَ عَلَيْكَ يَا وَلَدِي.", "segs": null, "full_uz": "Sizga hech gap yo'q, o'g'lim.", "note": null},
{"num": 56, "time": "00:04:37,779 --> 00:04:40,540", "arabic": "السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ.", "segs": null, "full_uz": "Mo'minlar amiriga va uning sheriklariga salom bo'lsin.", "note": null},
{"num": 57, "time": "00:04:40,540 --> 00:04:41,699", "arabic": "وَعَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
{"num": 58, "time": "00:04:41,699 --> 00:04:46,259", "arabic": "الْبِشَارَةُ يَا أَمِيرَ الْمُؤْمِنِينَ، الْبِشَارَةُ!", "segs": null, "full_uz": "Xushxabar, ey mo'minlar amiri, xushxabar!", "note": null},
{"num": 59, "time": "00:04:46,259 --> 00:04:47,939", "arabic": "هَاتِ مَا عِنْدَكَ.", "segs": null, "full_uz": "Nima gap bo'lsa, ayt.", "note": null},
{"num": 60, "time": "00:04:47,939 --> 00:04:55,219", "arabic": "انْتَصَرَ قَائِدُنَا الْبَطَلُ الْأَفْشِينُ عَلَى بَابَكَ الْخُرَّمِيِّ، وَفَرَّقَ أَتْبَاعَهُ، وَهُوَ الْآنَ فِي طَرِيقِهِ إِلَيْنَا.", "segs": [{"ar": "انْتَصَرَ قَائِدُنَا الْبَطَلُ الْأَفْشِينُ عَلَى بَابَكَ الْخُرَّمِيِّ،", "uz": "Qahramon qo'mondonimiz Afshin Bobak al-Xurramiy ustidan g'alaba qozondi va"}, {"ar": "وَفَرَّقَ أَتْبَاعَهُ، وَهُوَ الْآنَ فِي طَرِيقِهِ إِلَيْنَا.", "uz": "uning izdoshlarini tarqatib yubordi, u hozir bizga tomon yo'lda."}], "full_uz": "Qahramon qo'mondonimiz Afshin Bobak al-Xurramiy ustidan g'alaba qozondi va uning izdoshlarini tarqatib yubordi, u hozir bizga tomon yo'lda.", "note": null},
{"num": 63, "time": "00:04:55,219 --> 00:04:58,439", "arabic": "وَعَدُوُّ اللَّهِ الْخُرَّمِيُّ أَسِيرٌ عِنْدِي.", "segs": null, "full_uz": "Allohning dushmani al-Xurramiy esa mening qo'limda asirdir.", "note": null},
{"num": 64, "time": "00:04:58,439 --> 00:05:00,560", "arabic": "اللَّهُ أَكْبَرُ.", "segs": null, "full_uz": "Allohu akbar.", "note": null},
{"num": 65, "time": "00:05:00,560 --> 00:05:14,920", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي أَيَّدَ أَمِيرَ الْمُؤْمِنِينَ بِنَصْرٍ مِنْ عِنْدِهِ، وَمَا أَرَى ذَلِكَ إِلَّا دَعْوَةً صَالِحَةً لِوَلِيِّ أَمْرِنَا الْمُعْتَصِمِ.", "segs": [{"ar": "الْحَمْدُ لِلَّهِ الَّذِي أَيَّدَ", "uz": "Mo'minlar amirini O'z tomonidan"}, {"ar": "أَمِيرَ الْمُؤْمِنِينَ بِنَصْرٍ مِنْ عِنْدِهِ،", "uz": "g'alaba bilan qo'llab-quvvatlagan Allohga hamd bo'lsin,"}, {"ar": "وَمَا أَرَى ذَلِكَ إِلَّا دَعْوَةً صَالِحَةً لِوَلِيِّ أَمْرِنَا الْمُعْتَصِمِ.", "uz": "buni faqat rahbarimiz Mu'tasim uchun solih bir duo deb bilaman."}], "full_uz": "Mo'minlar amirini O'z tomonidan g'alaba bilan qo'llab-quvvatlagan Allohga hamd bo'lsin, buni faqat rahbarimiz Mu'tasim uchun solih bir duo deb bilaman.", "note": null},
{"num": 67, "time": "00:05:14,920 --> 00:05:29,500", "arabic": "إِنَّ أَمِيرَ الْمُؤْمِنِينَ الْمُعْتَصِمَ رَجُلٌ فِي خِدْمَةِ أَهْلِهِ وَرَعِيَّتِهِ مِنَ الْمُسْلِمِينَ، لَوْلَا تِلْكَ الْبِطَانَةُ السَّيِّئَةُ الَّتِي تَلْتَفُّ حَوْلَهُ.", "segs": [{"ar": "إِنَّ أَمِيرَ الْمُؤْمِنِينَ الْمُعْتَصِمَ رَجُلٌ فِي خِدْمَةِ أَهْلِهِ وَرَعِيَّتِهِ مِنَ الْمُسْلِمِينَ،", "uz": "Mo'minlar amiri Mu'tasim o'z ahli va musulmon fuqarolariga xizmat qiluvchi odam,"}, {"ar": "لَوْلَا تِلْكَ الْبِطَانَةُ السَّيِّئَةُ الَّتِي تَلْتَفُّ حَوْلَهُ.", "uz": "agar uning atrofini o'ragan o'sha yomon maslahatchilar bo'lmaganida edi."}], "full_uz": "Mo'minlar amiri Mu'tasim o'z ahli va musulmon fuqarolariga xizmat qiluvchi odam, agar uning atrofini o'ragan o'sha yomon maslahatchilar bo'lmaganida edi.", "note": null},
{"num": 70, "time": "00:05:29,500 --> 00:05:32,700", "arabic": "أَتَقْصِدُ الْمُعْتَزِلَةَ يَا أَبَا نَصْرٍ؟", "segs": null, "full_uz": "Mu'tazilani nazarda tutyapsizmi, ey Abu Nasr?", "note": null},
{"num": 71, "time": "00:05:32,700 --> 00:05:46,639", "arabic": "أَجَلْ يَا طَالِبُ يَا وَلَدِي، وَمَنْ غَيْرُ الْمُعْتَزِلَةِ أَصْحَابِ الْبِدَعِ وَالضَّلَالَةِ أَهْلٌ لِأَنْ يُوصَفَ بِبِطَانَةِ السُّوءِ الَّذِينَ حَذَّرَنَا مِنْهُمُ اللَّهُ فِي قُرْآنِهِ؟", "segs": [{"ar": "أَجَلْ يَا طَالِبُ يَا وَلَدِي،", "uz": "Ha, ey Tolib, o'g'lim,"}, {"ar": "وَمَنْ غَيْرُ الْمُعْتَزِلَةِ أَصْحَابِ الْبِدَعِ", "uz": "bid'at va adashuv egalari bo'lgan Mu'tazilliklardan"}, {"ar": "وَالضَّلَالَةِ أَهْلٌ لِأَنْ يُوصَفَ بِبِطَانَةِ السُّوءِ", "uz": "boshqa kim Alloh Qur'onida bizni ogohlantirgan"}, {"ar": "الَّذِينَ حَذَّرَنَا مِنْهُمُ اللَّهُ فِي قُرْآنِهِ؟", "uz": "yomon maslahatchilar deb atalishga loyiq bo'lardi?"}], "full_uz": "Ha, ey Tolib, o'g'lim, bid'at va adashuv egalari bo'lgan Mu'tazilliklardan boshqa kim Alloh Qur'onida bizni ogohlantirgan yomon maslahatchilar deb atalishga loyiq bo'lardi?", "note": "Qur'onda \"bitona\" (yaqin sirdosh)ni faqat o'z jamoasidan tanlash haqidagi ogohlantirishga ishora (Oli Imron surasi, 118-oyat)."},
{"num": 75, "time": "00:05:46,639 --> 00:05:51,560", "arabic": "مَا دَامَتْ بِطَانَةً كَمَا تَقُولُ، فَلِمَ يُبْقِيهِمُ الْمُعْتَصِمُ فِي قَصْرِهِ؟", "segs": [{"ar": "مَا دَامَتْ بِطَانَةً كَمَا تَقُولُ،", "uz": "Sen aytganingdek, yomon sirdosh ekan,"}, {"ar": "فَلِمَ يُبْقِيهِمُ الْمُعْتَصِمُ فِي قَصْرِهِ؟", "uz": "nega Mu'tasim ularni saroyida saqlaydi?"}], "full_uz": "Sen aytganingdek, yomon sirdosh ekan, nega Mu'tasim ularni saroyida saqlaydi?", "note": null},
{"num": 77, "time": "00:05:51,560 --> 00:05:52,299", "arabic": "يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Ey Ibn Siroj.", "note": null},
{"num": 78, "time": "00:05:52,299 --> 00:06:09,219", "arabic": "إِنَّهُ خَطَأُ أَخِيهِ الْمَأْمُونِ، فَهُوَ الَّذِي كَانَ يَدِينُ بِدِينِ الْمُعْتَزِلَةِ وَيُقَرِّبُهُمْ إِلَى دِيوَانِهِ، وَقَدْ كَانَتْ وَصِيَّتُهُ لِأَخِيهِ أَمِيرِ الْمُؤْمِنِينَ أَبِي إِسْحَاقَ الْمُعْتَصِمِ.", "segs": [{"ar": "إِنَّهُ خَطَأُ أَخِيهِ الْمَأْمُونِ،", "uz": "Bu uning akasi Ma'munning xatosi,"}, {"ar": "فَهُوَ الَّذِي كَانَ يَدِينُ بِدِينِ الْمُعْتَزِلَةِ", "uz": "chunki u Mu'tazila diniga e'tiqod qilib,"}, {"ar": "وَيُقَرِّبُهُمْ إِلَى دِيوَانِهِ،", "uz": "ularni o'z devoniga yaqinlashtirgan edi,"}, {"ar": "وَقَدْ كَانَتْ وَصِيَّتُهُ لِأَخِيهِ أَمِيرِ الْمُؤْمِنِينَ أَبِي إِسْحَاقَ الْمُعْتَصِمِ.", "uz": "va uning ukasi mo'minlar amiri Abu Ishoq al-Mu'tasimga vasiyati ham shu edi."}], "full_uz": "Bu uning akasi Ma'munning xatosi, chunki u Mu'tazila diniga e'tiqod qilib, ularni o'z devoniga yaqinlashtirgan edi, va uning ukasi mo'minlar amiri Abu Ishoq al-Mu'tasimga vasiyati ham shu edi.", "note": null},
{"num": 83, "time": "00:06:09,220 --> 00:06:33,160", "arabic": "وَلَكِنْ لَمَّا مُنِعَ الْإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ مِنَ التَّدْرِيسِ وَنَشْرِ عِلْمِهِ كَمَا كَانَ فِي السَّابِقِ، لَقَدْ حَاكَ الْمُعْتَزِلَةُ لَهُ الْمُؤَامَرَاتِ بَعْدَ أَنْ أَطْلَقَ أَمِيرُ الْمُؤْمِنِينَ سَرَاحَهُ، فَآثَرَ الْإِمَامُ أَنْ لَا يُعْطِيَ الْمُعْتَزِلَةَ فُرْصَةً أُخْرَى لِإِثَارَةِ فِتْنَةٍ أَكْبَرَ بَعْدَ الْتِفَافِ النَّاسِ حَوْلَهُ، فَلَزِمَ دَارَهُ.", "segs": [{"ar": "وَلَكِنْ لَمَّا مُنِعَ الْإِمَامُ أَحْمَدُ بْنُ حَنْبَلٍ مِنَ التَّدْرِيسِ وَنَشْرِ عِلْمِهِ كَمَا كَانَ فِي السَّابِقِ", "uz": "Lekin Imom Ahmad ibn Hanbal ilgarigidek dars berish va ilmini tarqatishdan man qilinganida"}, {"ar": "لَقَدْ حَاكَ الْمُعْتَزِلَةُ لَهُ الْمُؤَامَرَاتِ بَعْدَ أَنْ أَطْلَقَ أَمِيرُ الْمُؤْمِنِينَ سَرَاحَهُ", "uz": "mo'minlar amiri uni ozod qilganidan keyin Mu'tazila unga qarshi fitnalar to'qigan edi"}, {"ar": "فَآثَرَ الْإِمَامُ أَنْ لَا يُعْطِيَ الْمُعْتَزِلَةَ فُرْصَةً أُخْرَى لِإِثَارَةِ فِتْنَةٍ أَكْبَرَ بَعْدَ الْتِفَافِ النَّاسِ حَوْلَهُ", "uz": "Shuning uchun Imom, odamlar uning atrofida to'planganidan keyin, Mu'tazilaga yana katta fitna ko'tarishga imkoniyat bermaslikni afzal ko'rdi"}, {"ar": "فَلَزِمَ دَارَهُ", "uz": "va uyida o'tirib qoldi"}], "full_uz": "Lekin Imom Ahmad ibn Hanbal ilgarigidek dars berish va ilmini tarqatishdan man qilinganida, mo'minlar amiri uni ozod qilganidan keyin Mu'tazila unga qarshi fitnalar to'qigan edi. Shuning uchun Imom, odamlar uning atrofida to'planganidan keyin, Mu'tazilaga yanada katta fitna ko'tarishga yana bir imkoniyat bermaslikni afzal ko'rib, uyida o'tirib qoldi.", "note": null},
{"num": 88, "time": "00:06:33,160 --> 00:06:40,319", "arabic": "دَعُونَا الْآنَ مِنَ الْمُعْتَزِلَةِ وَفِتَنِهِمْ، وَلَا تُضَيِّعُوا فَرْحَتَنَا بِالْخَلَاصِ مِنْ هَذَا الْمُجْرِمِ بَابَكَ الْخُرَّمِيِّ.", "segs": [{"ar": "دَعُونَا الْآنَ مِنَ الْمُعْتَزِلَةِ وَفِتَنِهِمْ،", "uz": "Mu'tazila va ularning fitnalarini hozir qo'yib turaylik,"}, {"ar": "وَلَا تُضَيِّعُوا فَرْحَتَنَا بِالْخَلَاصِ مِنْ هَذَا الْمُجْرِمِ بَابَكَ الْخُرَّمِيِّ.", "uz": "bu jinoyatchi Bobak al-Xurramiydan qutulganimizdan quvonchimizni yo'qotmaylik."}], "full_uz": "Mu'tazila va ularning fitnalarini hozir qo'yib turaylik, bu jinoyatchi Bobak al-Xurramiydan qutulganimizdan quvonchimizni yo'qotmaylik.", "note": null},
{"num": 90, "time": "00:06:40,319 --> 00:07:19,680", "arabic": "أَنْتِ دَائِمًا عَلَى حَقٍّ، جَزَاكِ اللَّهُ يَا أُمَّ صَالِحٍ خَيْرًا.", "segs": [{"ar": "أَنْتِ دَائِمًا عَلَى حَقٍّ،", "uz": "Sen har doim haqsan,"}, {"ar": "جَزَاكِ اللَّهُ يَا أُمَّ صَالِحٍ خَيْرًا.", "uz": "Alloh senga yaxshilik bersin, ey Solihning onasi."}], "full_uz": "Sen har doim haqsan, Alloh senga yaxshilik bersin, ey Solihning onasi.", "note": null},
{"num": 92, "time": "00:07:19,680 --> 00:07:41,800", "arabic": "لَقَدْ كُنْتِ لِي خَيْرَ الْأَهْلِ وَكُنْتِ لِي نِعْمَ السَّنَدَ، لَقَدْ قَضَيْتُ مَعَكِ مَا يُقَارِبُ أَكْثَرَ مِنْ عِشْرِينَ سَنَةً لَمْ أَرَ مِنْكِ فِيهَا إِلَّا مَا يَسُرُّ، وَلَمْ تَرُدِّي لِي كَلِمَةً فِي حَقٍّ.", "segs": [{"ar": "لَقَدْ كُنْتِ لِي خَيْرَ الْأَهْلِ وَكُنْتِ لِي نِعْمَ السَّنَدَ،", "uz": "Sen menga eng yaxshi oila va eng yaxshi tayanch bo'lding,"}, {"ar": "لَقَدْ قَضَيْتُ مَعَكِ مَا يُقَارِبُ أَكْثَرَ مِنْ عِشْرِينَ سَنَةً", "uz": "sen bilan yigirma yildan ortiq umr o'tkazdim,"}, {"ar": "لَمْ أَرَ مِنْكِ فِيهَا إِلَّا مَا يَسُرُّ،", "uz": "bu davrda sendan faqat quvonch keltiradigan narsani ko'rdim,"}, {"ar": "وَلَمْ تَرُدِّي لِي كَلِمَةً فِي حَقٍّ.", "uz": "va haq gapimga hech qachon qarshi chiqmading."}], "full_uz": "Sen menga eng yaxshi oila va eng yaxshi tayanch bo'lding. Sen bilan yigirma yildan ortiq umr o'tkazdim, bu davrda sendan faqat quvonch keltiradigan narsani ko'rdim, va haq gapimga hech qachon qarshi chiqmading.", "note": null},
{"num": 96, "time": "00:07:41,800 --> 00:07:47,360", "arabic": "صَبَرْتِ حَيْثُ يَجِبُ الصَّبْرُ.", "segs": null, "full_uz": "Sabr kerak bo'lgan joyda sabr qilding.", "note": null},
{"num": 97, "time": "00:07:47,360 --> 00:07:51,560", "arabic": "شَفَاكِ اللَّهُ وَعَافَاكِ يَا أُمَّ وَلَدِي.", "segs": null, "full_uz": "Alloh senga shifo va ofiyat bersin, ey o'g'limning onasi.", "note": null},
{"num": 98, "time": "00:07:51,560 --> 00:08:00,259", "arabic": "اللَّهُمَّ اشْفِهَا مِمَّا تَجِدُ وَتُحَاذِرُ، اللَّهُمَّ سَلِّمْ.", "segs": null, "full_uz": "Ey Alloh, uni his qilayotgan va qo'rqayotgan narsadan shifolantir, ey Alloh, omon qil.", "note": null},
{"num": 101, "time": "00:09:03,580 --> 00:09:14,020", "arabic": "أَسِيرًا بَيْنَ أَيْدِينَا، وَسَيَنَالُ جَزَاءَ مَا يَسْتَحِقُّ، هَذَا هُوَ عَدُوُّ اللَّهِ بَابَكُ الْخُرَّمِيُّ.", "segs": [{"ar": "أَسِيرًا بَيْنَ أَيْدِينَا، وَسَيَنَالُ جَزَاءَ مَا يَسْتَحِقُّ،", "uz": "Bizning qo'limizda asir, va loyiq bo'lgan jazosini oladi,"}, {"ar": "هَذَا هُوَ عَدُوُّ اللَّهِ بَابَكُ الْخُرَّمِيُّ.", "uz": "mana bu Allohning dushmani Bobak al-Xurramiydir."}], "full_uz": "Bizning qo'limizda asir, va loyiq bo'lgan jazosini oladi, mana bu Allohning dushmani Bobak al-Xurramiydir.", "note": null},
{"num": 107, "time": "00:10:10,019 --> 00:10:11,139", "arabic": "يَا اللَّهُ.", "segs": null, "full_uz": "Yo Alloh.", "note": null},
{"num": 108, "time": "00:10:11,139 --> 00:10:31,600", "arabic": "رَحِمَكِ اللَّهُ يَا أُمَّ صَالِحٍ، كُنْتِ خَيْرَ زَوْجَةٍ لِي وَخَيْرَ سَنَدٍ.", "segs": [{"ar": "رَحِمَكِ اللَّهُ يَا أُمَّ صَالِحٍ،", "uz": "Alloh senga rahmat qilsin, ey Solihning onasi,"}, {"ar": "كُنْتِ خَيْرَ زَوْجَةٍ لِي وَخَيْرَ سَنَدٍ.", "uz": "sen menga eng yaxshi xotin va eng yaxshi tayanch eding."}], "full_uz": "Alloh senga rahmat qilsin, ey Solihning onasi, sen menga eng yaxshi xotin va eng yaxshi tayanch eding.", "note": null},
{"num": 111, "time": "00:10:31,600 --> 00:10:37,939", "arabic": "أَهْوَنُ عَلَيْكَ يَا وَلَدِي.", "segs": null, "full_uz": "Senga yengil bo'lsin, o'g'lim.", "note": null},
{"num": 113, "time": "00:10:37,939 --> 00:10:38,960", "arabic": "وَادْعُ لَهَا.", "segs": null, "full_uz": "Va u uchun duo qil.", "note": null},
{"num": 114, "time": "00:10:40,019 --> 00:10:47,419", "arabic": "رَحِمَكِ اللَّهُ يَا أُمِّي، وَأَسْكَنَكِ فُسَيْحَ جِنَانِهِ.", "segs": null, "full_uz": "Alloh senga rahmat qilsin, onajon, va seni Jannatining keng-mo'l joyiga joylashtirsin.", "note": null},
{"num": 116, "time": "00:10:47,419 --> 00:10:54,559", "arabic": "هَيَّا يَا وَلَدِي هَيَّا، قُمْ هَيَّا.", "segs": null, "full_uz": "Yur, o'g'lim, yur, tur, yur.", "note": null},
{"num": 118, "time": "00:11:10,019 --> 00:11:25,079", "arabic": "أَهَذَا هُوَ مَنْ نَشَرَ الرُّعْبَ وَالْقَتْلَ فِي بِلَادِ الْمُسْلِمِينَ طِيلَةَ عِشْرِينَ عَامًا؟", "segs": [{"ar": "أَهَذَا هُوَ مَنْ نَشَرَ الرُّعْبَ", "uz": "Yigirma yil davomida musulmonlar yurtida"}, {"ar": "وَالْقَتْلَ فِي بِلَادِ الْمُسْلِمِينَ طِيلَةَ عِشْرِينَ عَامًا؟", "uz": "vahima va qotillikni tarqatgan odam shumi?"}], "full_uz": "Yigirma yil davomida musulmonlar yurtida vahima va qotillikni tarqatgan odam shumi?", "note": null},
{"num": 119, "time": "00:11:25,079 --> 00:11:32,879", "arabic": "أَجَلْ يَا مَوْلَايَ، هَذَا هُوَ عَدُوُّ اللَّهِ بَابَكُ الْخُرَّمِيُّ.", "segs": null, "full_uz": "Ha, xo'jayinim, mana bu Allohning dushmani Bobak al-Xurramiydir.", "note": null},
{"num": 121, "time": "00:11:32,879 --> 00:11:36,659", "arabic": "يَنْبَغِي أَنْ يَكُونَ قَدْ أَعَدَّ الْعُدَّةَ لِمِثْلِ هَذَا الْيَوْمِ.", "segs": null, "full_uz": "U shunday kun uchun tayyorgarlik ko'rgan bo'lishi kerak edi.", "note": null},
{"num": 122, "time": "00:11:40,019 --> 00:12:18,720", "arabic": "كَمْ مَرَّةٍ يَجِبُ أَنْ أَقْتُلَكَ أَيُّهَا الْكَافِرُ حَتَّى أَقْتَصَّ لِمَنْ قَتَلْتَ مِنَ النِّسَاءِ وَالشُّيُوخِ وَالْأَطْفَالِ؟ كَمْ مَرَّةٍ يَجِبُ أَنْ يُمَزِّقَكَ سَيْفِي حَتَّى تَرْتَاحَ نُفُوسُ الْآلَافِ مِنَ الْمُسْلِمِينَ الَّذِينَ شَرَّدْتَهُمْ وَقَتَلْتَهُمْ؟ قَتَلْتَ النَّاسَ أَحْيَاءً وَحَرَقْتَهُمْ أَمْوَاتًا وَعَبَثْتَ بِأَشْلَائِهِمْ عَبَثَ الْكَلْبِ بِفَرِيسَتِهِ.", "segs": [{"ar": "كَمْ مَرَّةٍ يَجِبُ أَنْ أَقْتُلَكَ أَيُّهَا الْكَافِرُ حَتَّى أَقْتَصَّ لِمَنْ قَتَلْتَ مِنَ النِّسَاءِ وَالشُّيُوخِ وَالْأَطْفَالِ؟", "uz": "Necha marta seni o'ldirishim kerak, kofir, sen o'ldirgan ayollar, chollar va bolalar uchun qasos olguncha?"}, {"ar": "كَمْ مَرَّةٍ يَجِبُ أَنْ يُمَزِّقَكَ سَيْفِي حَتَّى تَرْتَاحَ نُفُوسُ الْآلَافِ مِنَ الْمُسْلِمِينَ الَّذِينَ شَرَّدْتَهُمْ وَقَتَلْتَهُمْ؟", "uz": "Necha marta qilichim seni parchalashi kerak, sen sarson qilib o'ldirgan minglab musulmonlarning ruhlari tinchlanguncha?"}, {"ar": "قَتَلْتَ النَّاسَ أَحْيَاءً وَحَرَقْتَهُمْ أَمْوَاتًا", "uz": "Sen odamlarni tirik holda o'ldirding, o'liklarini yoqding"}, {"ar": "وَعَبَثْتَ بِأَشْلَائِهِمْ عَبَثَ الْكَلْبِ بِفَرِيسَتِهِ", "uz": "jasadlarini it o'z o'ljasini talagandek talading"}], "full_uz": "Necha marta seni o'ldirishim kerak, ey kofir, sen o'ldirgan ayollar, chollar va bolalar uchun qasos olguncha? Necha marta qilichim seni parchalashi kerak, sen sarson qilib o'ldirgan minglab musulmonlarning ruhlari tinchlanguncha? Sen odamlarni tirik holda o'ldirding, o'liklarini yoqding, jasadlarini it o'z o'ljasini talagandek talading.", "note": null},
{"num": 131, "time": "00:12:18,720 --> 00:12:21,679", "arabic": "اللَّعْنَةُ عَلَيْكَ.", "segs": null, "full_uz": "La'nat senga.", "note": null},
{"num": 132, "time": "00:12:37,039 --> 00:12:40,219", "arabic": "أَيُّهَا الْحَرَسُ، نَفِّذُوا.", "segs": null, "full_uz": "Ey qorovullar, ijro eting.", "note": null},
{"num": 134, "time": "00:12:40,219 --> 00:12:46,500", "arabic": "اللَّهُ أَكْبَرُ.", "segs": null, "full_uz": "Allohu akbar.", "note": null},
{"num": 135, "time": "00:13:08,559 --> 00:13:44,500", "arabic": "كَانَ الْمَلْعُونُ بَابَكُ الْخُرَّمِيُّ يَأْمُرُ رِجَالَهُ فِي حُرُوبِهِ أَلَّا يَدَعُوا رَجُلًا وَلَا امْرَأَةً وَلَا صَبِيًّا وَلَا طِفْلَةً إِلَّا قَتَلُوهُ وَاغْتَالُوهُ، حَتَّى دَخَلَ النَّاسَ بِسَبَبِهِ رُعْبٌ شَدِيدٌ وَهَوْلٌ عَظِيمٌ. لَقَدِ احْتَلَّ بَابَكُ الْخُرَّمِيُّ مُدُنًا وَقُرًى، وَأَخَذَ بِالتَّمْثِيلِ بِالنَّاسِ وَالتَّحْرِيقِ بِالنَّارِ، وَعَاثَ فِي الْأَرْضِ فَسَادًا، وَأَهْلَكَ النَّسْلَ وَالزَّرْعَ، وَهَزَمَ لِلسُّلْطَانِ جُيُوشًا كَثِيرَةً، وَقَتَلَ عِدَّةً مِنْ قَادَتِهِ.", "segs": [{"ar": "كَانَ الْمَلْعُونُ بَابَكُ الْخُرَّمِيُّ يَأْمُرُ رِجَالَهُ فِي حُرُوبِهِ أَلَّا يَدَعُوا رَجُلًا وَلَا امْرَأَةً وَلَا صَبِيًّا وَلَا طِفْلَةً إِلَّا قَتَلُوهُ وَاغْتَالُوهُ", "uz": "La'natlangan Bobak al-Xurramiy jangchilariga biror erkak, ayol, o'g'il yoki qiz bolani tirik qoldirmasdan o'ldirishlarini buyurar edi"}, {"ar": "حَتَّى دَخَلَ النَّاسَ بِسَبَبِهِ رُعْبٌ شَدِيدٌ وَهَوْلٌ عَظِيمٌ", "uz": "toki odamlar orasiga uning sababidan qattiq vahima va dahshat kirdi"}, {"ar": "لَقَدِ احْتَلَّ بَابَكُ الْخُرَّمِيُّ مُدُنًا وَقُرًى، وَأَخَذَ بِالتَّمْثِيلِ بِالنَّاسِ وَالتَّحْرِيقِ بِالنَّارِ", "uz": "u shaharlar va qishloqlarni bosib oldi, odamlarni qiynab-o'ldirib, o'tda yoqdi"}, {"ar": "وَعَاثَ فِي الْأَرْضِ فَسَادًا، وَأَهْلَكَ النَّسْلَ وَالزَّرْعَ", "uz": "yer yuzida fasod tarqatdi, nasl va ekinlarni yo'q qildi"}, {"ar": "وَهَزَمَ لِلسُّلْطَانِ جُيُوشًا كَثِيرَةً، وَقَتَلَ عِدَّةً مِنْ قَادَتِهِ", "uz": "sultonning ko'p qo'shinlarini mag'lub etdi va bir necha qo'mondonini o'ldirdi"}], "full_uz": "La'natlangan Bobak al-Xurramiy o'z jangchilariga urushlarida biror erkak, ayol, o'g'il yoki qiz bolani tirik qoldirmasdan o'ldirishlarini buyurar edi, toki odamlar orasiga uning sababidan qattiq vahima va dahshat kirdi. Bobak al-Xurramiy shaharlar va qishloqlarni bosib oldi, odamlarni qiynab-o'ldirib, o'tda yoqib yubordi, yer yuzida fasod tarqatdi, nasl va ekinlarni yo'q qildi, sultonning ko'p qo'shinlarini mag'lub etdi va uning qo'mondonlaridan bir nechtasini o'ldirdi.", "note": null},
{"num": 145, "time": "00:13:44,500 --> 00:13:51,280", "arabic": "يُقَالُ إِنَّ مَجْمُوعَ مَنْ قَتَلَهُمْ بَابَكُ الْخُرَّمِيُّ مِئَتَانِ وَخَمْسَةٌ وَخَمْسُونَ أَلْفَ مُسْلِمٍ أَوْ يَزِيدُ.", "segs": [{"ar": "يُقَالُ إِنَّ مَجْمُوعَ مَنْ قَتَلَهُمْ بَابَكُ الْخُرَّمِيُّ مِئَتَانِ", "uz": "Aytilishicha, Bobak al-Xurramiy o'ldirgan musulmonlarning umumiy soni ikki yuz"}, {"ar": "وَخَمْسَةٌ وَخَمْسُونَ أَلْفَ مُسْلِمٍ أَوْ يَزِيدُ.", "uz": "ellik besh ming yoki undan ko'p bo'lgan."}], "full_uz": "Aytilishicha, Bobak al-Xurramiy o'ldirgan musulmonlarning umumiy soni ikki yuz ellik besh ming yoki undan ko'p bo'lgan.", "note": null},
{"num": 147, "time": "00:13:51,280 --> 00:13:57,300", "arabic": "الْحَمْدُ لِلَّهِ، هَذَا مِنْ أَعْظَمِ الْفُتُوحِ فِي الْإِسْلَامِ.", "segs": null, "full_uz": "Alhamdulillah, bu Islomdagi eng buyuk fathlardan biridir.", "note": null},
{"num": 149, "time": "00:13:57,300 --> 00:14:05,040", "arabic": "جَزَى اللَّهُ أَمِيرَ الْمُؤْمِنِينَ عَنِ الْمُسْتَضْعَفِينَ مِنَ الْوِلْدَانِ وَالنِّسَاءِ وَالشُّيُوخِ كُلَّ خَيْرٍ.", "segs": [{"ar": "جَزَى اللَّهُ أَمِيرَ الْمُؤْمِنِينَ عَنِ الْمُسْتَضْعَفِينَ مِنَ الْوِلْدَانِ", "uz": "Alloh mo'minlar amiriga ojiz qolgan bolalar,"}, {"ar": "وَالنِّسَاءِ وَالشُّيُوخِ كُلَّ خَيْرٍ.", "uz": "ayollar va chollar nomidan barcha yaxshiliklarni bersin."}], "full_uz": "Alloh mo'minlar amiriga ojiz qolgan bolalar, ayollar va chollar nomidan barcha yaxshiliklarni bersin.", "note": null},
{"num": 151, "time": "00:14:05,039 --> 00:14:10,480", "arabic": "إِنَّ اللَّهَ لَيَزَعُ بِالسُّلْطَانِ مَا لَا يَزَعُ بِالْقُرْآنِ.", "segs": null, "full_uz": "Alloh sulton (hokimiyat) orqali Qur'on orqali to'xtatmagan narsani ham to'xtatadi.", "note": "\"إن الله ليزع بالسلطان ما لا يزع بالقرآن\" — Usmon ibn Affon (r.a.)ga nisbat berilgan mashhur ibora."},
{"num": 153, "time": "00:14:10,480 --> 00:14:22,179", "arabic": "وَكَيْفَ حَالُ الْإِمَامِ الْآنَ؟", "segs": null, "full_uz": "Imomning hozirgi ahvoli qalay?", "note": null},
{"num": 154, "time": "00:14:22,179 --> 00:14:32,799", "arabic": "مَا زَالَ يَذْكُرُهَا فِي نَفْسِهِ يَا أَبَا أَحْمَدَ، لَقَدْ لَفَّهُ الْحُزْنُ حَتَّى مَلَكَهُ، لَكِنَّهُ يَتَلَفَّعُ بِالصَّبْرِ حَتَّى يُقَوِّيَنِي وَيُقَوِّيَ نَفْسَهُ.", "segs": [{"ar": "مَا زَالَ يَذْكُرُهَا فِي نَفْسِهِ يَا أَبَا أَحْمَدَ،", "uz": "U hali ham uni ichida eslab yuribdi, ey Abu Ahmad,"}, {"ar": "لَقَدْ لَفَّهُ الْحُزْنُ حَتَّى مَلَكَهُ،", "uz": "g'am uni o'rab, egallab oldi,"}, {"ar": "لَكِنَّهُ يَتَلَفَّعُ بِالصَّبْرِ حَتَّى يُقَوِّيَنِي وَيُقَوِّيَ نَفْسَهُ.", "uz": "lekin u meni va o'zini quvvatlantirish uchun sabrga o'ranib olyapti."}], "full_uz": "U hali ham uni ichida eslab yuribdi, ey Abu Ahmad, g'am uni o'rab, egallab oldi, lekin u meni va o'zini quvvatlantirish uchun sabrga o'ranib olyapti.", "note": null},
{"num": 157, "time": "00:14:32,799 --> 00:14:35,379", "arabic": "كَانَ اللَّهُ فِي عَوْنِي.", "segs": null, "full_uz": "Alloh menga yordamchi bo'ldi.", "note": null},
{"num": 158, "time": "00:14:35,379 --> 00:14:41,240", "arabic": "رَحِمَ اللَّهُ أُمَّ صَالِحٍ فَلَقَدْ كَانَتْ عَوْنًا وَسَنَدًا، رَحِمَهَا اللَّهُ.", "segs": [{"ar": "رَحِمَ اللَّهُ أُمَّ صَالِحٍ فَلَقَدْ كَانَتْ عَوْنًا وَسَنَدًا،", "uz": "Alloh Solihning onasiga rahmat qilsin, u yordamchi va tayanch edi,"}, {"ar": "رَحِمَهَا اللَّهُ.", "uz": "Alloh unga rahmat qilsin."}], "full_uz": "Alloh Solihning onasiga rahmat qilsin, u yordamchi va tayanch edi, Alloh unga rahmat qilsin.", "note": null},
{"num": 160, "time": "00:14:41,240 --> 00:14:52,179", "arabic": "وَلَكِنْ لَا بُدَّ أَنْ يَكُونَ إِلَى جَانِبِ الْإِمَامِ مَنْ يَرْعَاهُ يَا أَبَا الْفَضْلِ، قَدْ عَرَضْتُ عَلَيْهِ أَنْ نَنْتَقِلَ أَنَا وَزَوْجِي إِلَى دَارِهِ فَأَبَى.", "segs": [{"ar": "وَلَكِنْ لَا بُدَّ أَنْ يَكُونَ إِلَى", "uz": "Lekin Imomning yonida uni parvarish qiladigan kishi bo'lishi shart,"}, {"ar": "جَانِبِ الْإِمَامِ مَنْ يَرْعَاهُ يَا أَبَا الْفَضْلِ،", "uz": "ey Abu al-Fazl. Men va erim"}, {"ar": "قَدْ عَرَضْتُ عَلَيْهِ أَنْ نَنْتَقِلَ أَنَا", "uz": "uning uyiga ko'chib o'tishimizni taklif qildim,"}, {"ar": "وَزَوْجِي إِلَى دَارِهِ فَأَبَى.", "uz": "lekin u rad etdi."}], "full_uz": "Lekin Imomning yonida uni parvarish qiladigan kishi bo'lishi shart, ey Abu al-Fazl. Men va erim uning uyiga ko'chib o'tishimizni taklif qildim, lekin u rad etdi.", "note": null},
{"num": 162, "time": "00:14:52,179 --> 00:14:59,139", "arabic": "أَعْذِرْنِي يَا أَبَا الْفَضْلِ، وَلَكِنِّي أَرَى أَنَّ بَقَاءَ الْإِمَامِ دُونَ زَوْجٍ وَهُوَ فِي هَذَا الْعُمْرِ صَعْبٌ عَلَيْهِ.", "segs": [{"ar": "أَعْذِرْنِي يَا أَبَا الْفَضْلِ،", "uz": "Meni ma'zur tuting,"}, {"ar": "وَلَكِنِّي أَرَى أَنَّ بَقَاءَ الْإِمَامِ دُونَ زَوْجٍ", "uz": "ey Abu al-Fazl, lekin men Imomning bu yoshda"}, {"ar": "وَهُوَ فِي هَذَا الْعُمْرِ صَعْبٌ عَلَيْهِ.", "uz": "xotinsiz qolishini o'ziga og'ir deb bilaman."}], "full_uz": "Meni ma'zur tuting, ey Abu al-Fazl, lekin men Imomning bu yoshda xotinsiz qolishini o'ziga og'ir deb bilaman.", "note": null},
{"num": 164, "time": "00:14:59,139 --> 00:15:05,500", "arabic": "أَنَا وَأُخْتُكَ أُمُّ الْفَضْلِ تَحَدَّثْنَا فِي هَذَا الشَّأْنِ مُطَوَّلًا، لَكِنَّنِي مُتَرَدِّدٌ فِي مُفَاتَحَتِهِ فِي هَذَا الْأَمْرِ.", "segs": [{"ar": "أَنَا وَأُخْتُكَ أُمُّ الْفَضْلِ تَحَدَّثْنَا فِي هَذَا الشَّأْنِ مُطَوَّلًا،", "uz": "Men va singlingiz Umm al-Fazl bu masalada uzoq gaplashdik,"}, {"ar": "لَكِنَّنِي مُتَرَدِّدٌ فِي مُفَاتَحَتِهِ فِي هَذَا الْأَمْرِ.", "uz": "lekin bu haqda unga gap ochishga ikkilanib turibman."}], "full_uz": "Men va singlingiz Umm al-Fazl bu masalada uzoq gaplashdik, lekin bu haqda unga gap ochishga ikkilanib turibman.", "note": null},
{"num": 166, "time": "00:15:05,500 --> 00:15:08,500", "arabic": "الْإِمَامُ يَا صَالِحُ تُؤْذِيهِ الْوَحْدَةُ وَالْوَحْشَةُ.", "segs": null, "full_uz": "Imomga yolg'izlik va vahima azob beryapti, ey Solih.", "note": null},
{"num": 167, "time": "00:15:08,500 --> 00:15:14,900", "arabic": "سَنَرَى مَا يَكُونُ إِنْ شَاءَ اللَّهُ.", "segs": null, "full_uz": "Nima bo'lishini ko'ramiz, inshaalloh.", "note": null},
{"num": 168, "time": "00:15:14,900 --> 00:15:27,800", "arabic": "رَحِمَكِ اللَّهُ يَا عَبَّاسَةُ، وَجَعَلَ مَثْوَاكِ الْجَنَّةَ.", "segs": null, "full_uz": "Alloh senga rahmat qilsin, ey Abbasa, va manzilingni Jannat qilsin.", "note": null},
{"num": 170, "time": "00:15:27,799 --> 00:15:43,099", "arabic": "الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَنَا أَيُّنَا أَحْسَنُ عَمَلًا، وَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ.", "segs": [{"ar": "الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ الْمَوْتَ", "uz": "Qaysimiz amalimiz yaxshiroq ekanini sinash uchun o'lim"}, {"ar": "وَالْحَيَاةَ لِيَبْلُوَنَا أَيُّنَا أَحْسَنُ عَمَلًا،", "uz": "va hayotni yaratgan Allohga hamd bo'lsin. Albatta,"}, {"ar": "وَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ.", "uz": "biz Allohnikimiz va albatta, Unga qaytuvchimiz."}], "full_uz": "Qaysimiz amalimiz yaxshiroq ekanini sinash uchun o'lim va hayotni yaratgan Allohga hamd bo'lsin. Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": "Qur'on, Mulk surasi, 2-oyat va Baqara surasi, 156-oyat."},
{"num": 173, "time": "00:15:57,799 --> 00:15:59,379", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 174, "time": "00:15:59,379 --> 00:16:01,120", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 175, "time": "00:16:01,120 --> 00:16:04,259", "arabic": "كَيْفَ أَصْبَحْتَ الْيَوْمَ يَا أَبِي؟", "segs": null, "full_uz": "Bugun qanday tong ottirdingiz, dadajon?", "note": null},
{"num": 176, "time": "00:16:04,259 --> 00:16:05,500", "arabic": "بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Yaxshi, alhamdulillah.", "note": null},
{"num": 177, "time": "00:16:05,500 --> 00:16:07,179", "arabic": "كَيْفَ حَالُ أَهْلِكَ يَا وَلَدِي؟", "segs": null, "full_uz": "Oilangning ahvoli qalay, o'g'lim?", "note": null},
{"num": 178, "time": "00:16:07,179 --> 00:16:08,459", "arabic": "الْحَمْدُ لِلَّهِ نَحْنُ بِخَيْرٍ.", "segs": null, "full_uz": "Alhamdulillah, biz yaxshimiz.", "note": null},
{"num": 179, "time": "00:16:08,459 --> 00:16:12,059", "arabic": "أَرْسَلَ مَعِي عُمَرُ الْإِسْكَافِيُّ أُجْرَةَ الدُّكَّانِ.", "segs": null, "full_uz": "Umar al-Iskofiy men bilan do'kon ijarasini yubordi.", "note": null},
{"num": 180, "time": "00:16:12,059 --> 00:16:15,699", "arabic": "لَسْتُ فِي حَاجَةٍ إِلَيْهَا، دَعْهَا عِنْدَكَ.", "segs": null, "full_uz": "Menga hojat yo'q, o'zingda qol.", "note": null},
{"num": 181, "time": "00:16:15,699 --> 00:16:20,559", "arabic": "نَحْنُ بِخَيْرٍ يَا أَبِي، كُلُّنَا بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Biz yaxshimiz, dadajon, hammamiz yaxshimiz, alhamdulillah.", "note": null},
{"num": 183, "time": "00:16:20,559 --> 00:16:23,579", "arabic": "لَكِنَّكَ ذُو أَهْلٍ وَعِيَالٍ وَتَحْتَاجُهَا.", "segs": null, "full_uz": "Lekin sizning oilangiz va bolalaringiz bor, sizga kerak.", "note": null},
{"num": 184, "time": "00:16:23,579 --> 00:16:25,599", "arabic": "مَا نَفَقَتِي حَتَّى آخُذَهَا؟", "segs": null, "full_uz": "Mening xarajatim qancha ediki, uni olsam?", "note": null},
{"num": 185, "time": "00:16:25,599 --> 00:16:27,379", "arabic": "هَيَّا يَا وَلَدِي، دَعْهَا عِنْدَكَ.", "segs": null, "full_uz": "Bo'pti, o'g'lim, o'zingda qol.", "note": null},
{"num": 186, "time": "00:16:27,799 --> 00:16:37,699", "arabic": "كُنْتُ أُرِيدُ أَنْ أُفَاتِحَكَ فِي أَمْرِ النُّوَّابِ.", "segs": null, "full_uz": "Sizga chegara qo'shinlari haqida gap ochmoqchi edim.", "note": null},
{"num": 187, "time": "00:16:37,699 --> 00:16:48,799", "arabic": "مَا الْخَبَرُ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Nima gap, xo'jayinim?", "note": null},
{"num": 188, "time": "00:16:50,799 --> 00:16:53,159", "arabic": "هَذِهِ رِسَالَةٌ مِنْ ثُغُورِ الشَّمَالِ.", "segs": null, "full_uz": "Bu shimoliy chegaralardan kelgan xat.", "note": null},
{"num": 189, "time": "00:16:53,159 --> 00:17:00,059", "arabic": "يُخْبِرُونَ فِيهَا أَنَّ مَلِكَ الرُّومِ تَوْفِيلَ بْنَ مِخَائِيلَ هَاجَمَ مَدِينَةَ زِبَطْرَةَ بِجُيُوشٍ جَرَّارَةٍ.", "segs": [{"ar": "يُخْبِرُونَ فِيهَا أَنَّ مَلِكَ الرُّومِ تَوْفِيلَ", "uz": "Unda Rum podshosi Tavfil ibn Mixoyil ulkan"}, {"ar": "بْنَ مِخَائِيلَ هَاجَمَ مَدِينَةَ زِبَطْرَةَ بِجُيُوشٍ جَرَّارَةٍ.", "uz": "qo'shinlar bilan Zibatra shahriga hujum qilgani xabar berilgan."}], "full_uz": "Unda Rum podshosi Tavfil ibn Mixoyil ulkan qo'shinlar bilan Zibatra shahriga hujum qilgani xabar berilgan.", "note": null},
{"num": 190, "time": "00:17:00,059 --> 00:17:03,519", "arabic": "وَلَا أَحَدَ يَعْرِفُ مَاذَا يَجْرِي هُنَاكَ.", "segs": null, "full_uz": "Va u yerda nima bo'layotganini hech kim bilmaydi.", "note": null},
{"num": 191, "time": "00:17:03,519 --> 00:17:07,299", "arabic": "أَلَيْسَ بَيْنَنَا وَبَيْنَ تَوْفِيلَ مُعَاهَدَاتٌ؟", "segs": null, "full_uz": "Biz bilan Tavfil o'rtasida shartnomalar yo'q edimi?", "note": null},
{"num": 192, "time": "00:17:07,299 --> 00:17:11,839", "arabic": "هَؤُلَاءِ قَوْمٌ نَكَثُوا بِعُهُودِهِمْ وَأَغَارُوا عَلَى الْآمِنِينَ فِي دِيَارِهِمْ.", "segs": null, "full_uz": "Bu qavm ahdlarini buzib, o'z yurtlaridagi tinch aholiga bostirib kirishdi.", "note": null},
{"num": 193, "time": "00:17:11,839 --> 00:17:20,740", "arabic": "الْأَخْبَارُ تَقُولُ يَا مَوْلَايَ إِنَّ فُلُولَ جَيْشِ بَابَكَ الْخُرَّمِيِّ قَدِ انْضَمَّتْ إِلَى جُيُوشِ تَوْفِيلَ بْنِ مِخَائِيلَ.", "segs": [{"ar": "الْأَخْبَارُ تَقُولُ يَا مَوْلَايَ", "uz": "Xabarlarga ko'ra, xo'jayinim,"}, {"ar": "إِنَّ فُلُولَ جَيْشِ بَابَكَ", "uz": "Bobak al-Xurramiy qo'shinining"}, {"ar": "الْخُرَّمِيِّ قَدِ انْضَمَّتْ إِلَى جُيُوشِ تَوْفِيلَ بْنِ مِخَائِيلَ.", "uz": "qoldiqlari Tavfil ibn Mixoylning qo'shinlariga qo'shilib ketgan."}], "full_uz": "Xabarlarga ko'ra, xo'jayinim, Bobak al-Xurramiy qo'shinining qoldiqlari Tavfil ibn Mixoylning qo'shinlariga qo'shilib ketgan.", "note": null},
{"num": 194, "time": "00:17:20,740 --> 00:17:23,319", "arabic": "نَحْنُ فِي انْتِظَارِ أَوَامِرِكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Biz sizning buyrug'ingizni kutyapmiz, xo'jayinim.", "note": null},
{"num": 195, "time": "00:17:23,319 --> 00:17:36,480", "arabic": "أُرِيدُكَ أَنْ تَذْهَبَ فَوْرًا إِلَى زِبَطْرَةَ، لَعَلَّكَ تَسْتَطِيعُ أَنْ تَفْعَلَ شَيْئًا قَبْلَ أَنْ يَعِيثَ فِيهَا عَدُوُّ اللَّهِ فَسَادًا. ارْحَلْ.", "segs": [{"ar": "أُرِيدُكَ أَنْ تَذْهَبَ فَوْرًا إِلَى زِبَطْرَةَ،", "uz": "Sendan darhol Zibatraga borishingni istayman,"}, {"ar": "لَعَلَّكَ تَسْتَطِيعُ أَنْ تَفْعَلَ شَيْئًا قَبْلَ أَنْ يَعِيثَ فِيهَا عَدُوُّ اللَّهِ", "uz": "balki Allohning dushmani u yerda fasod tarqatishidan oldin biror narsa qila olarsan."}, {"ar": "فَسَادًا. ارْحَلْ.", "uz": "Yo'lga chiq."}], "full_uz": "Sendan darhol Zibatraga borishingni istayman, balki Allohning dushmani u yerda fasod tarqatishidan oldin biror narsa qila olarsan. Yo'lga chiq.", "note": null},
{"num": 199, "time": "00:17:36,480 --> 00:17:38,420", "arabic": "السَّمْعُ وَالطَّاعَةُ يَا مَوْلَايَ.", "segs": null, "full_uz": "Eshitdik va bo'ysunamiz, xo'jayinim.", "note": null},
{"num": 200, "time": "00:17:38,420 --> 00:17:46,700", "arabic": "إِنْ كَانَ الْأَمْرُ كَمَا تَصِفُ يَا مَوْلَايَ، فَأَحْسِبُ أَنَّ عَدُوَّ اللَّهِ قَدْ نَالَ مُرَادَهُ مِنْهَا.", "segs": [{"ar": "إِنْ كَانَ الْأَمْرُ كَمَا تَصِفُ يَا مَوْلَايَ،", "uz": "Agar ish siz aytganidek bo'lsa, xo'jayinim,"}, {"ar": "فَأَحْسِبُ أَنَّ عَدُوَّ اللَّهِ", "uz": "Allohning dushmani u yerdan o'z"}, {"ar": "قَدْ نَالَ مُرَادَهُ مِنْهَا.", "uz": "maqsadiga erishgan deb o'ylayman."}], "full_uz": "Agar ish siz aytganidek bo'lsa, xo'jayinim, Allohning dushmani u yerdan o'z maqsadiga erishgan deb o'ylayman.", "note": null},
{"num": 202, "time": "00:17:46,700 --> 00:17:54,559", "arabic": "فَالْحَامِيَةُ الْمَوْجُودَةُ فِي زِبَطْرَةَ قَلِيلَةٌ، وَلَا أَظُنُّهَا سَوْفَ تَصْمُدُ أَمَامَ جَحَافِلِ تَوْفِيلَ الْمُجْرِمِ.", "segs": [{"ar": "فَالْحَامِيَةُ الْمَوْجُودَةُ فِي زِبَطْرَةَ قَلِيلَةٌ،", "uz": "Zibatradagi qo'riqchi qismi oz,"}, {"ar": "وَلَا أَظُنُّهَا سَوْفَ تَصْمُدُ أَمَامَ جَحَافِلِ تَوْفِيلَ الْمُجْرِمِ.", "uz": "va u jinoyatchi Tavfilning qo'shinlari oldida bardosh berishiga ishonmayman."}], "full_uz": "Zibatradagi qo'riqchi qismi oz, va u jinoyatchi Tavfilning qo'shinlari oldida bardosh berishiga ishonmayman.", "note": null},
{"num": 204, "time": "00:17:54,559 --> 00:18:03,100", "arabic": "أُقْسِمُ لَيَدْفَعَنَّ الثَّمَنَ غَالِيًا كَمَا دَفَعَهُ الْخُرَّمِيُّ مِنْ قَبْلُ.", "segs": null, "full_uz": "Qasam ichamanki, u ilgari al-Xurramiy to'lagandek qimmat narx to'laydi.", "note": null},
{"num": 207, "time": "00:18:03,100 --> 00:18:07,220", "arabic": "أَنَا ابْنُ هَارُونَ الرَّشِيدِ.", "segs": null, "full_uz": "Men Horun ar-Rashidning o'g'liman.", "note": null},
{"num": 208, "time": "00:18:07,220 --> 00:18:14,100", "arabic": "وَأَنَا رَأْيِي مِنْ رَأْيِ صَالِحٍ يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Mening fikrim ham Solihning fikriga qo'shiladi, ey Abu Abdulloh.", "note": null},
{"num": 209, "time": "00:18:14,100 --> 00:18:20,519", "arabic": "أَنْتَ بِحَاجَةٍ إِلَى امْرَأَةٍ تُعِينُكَ عَلَى نَوَائِبِ الْحَيَاةِ وَتُؤْنِسُ وَحْدَتَكَ.", "segs": [{"ar": "أَنْتَ بِحَاجَةٍ إِلَى امْرَأَةٍ تُعِينُكَ عَلَى نَوَائِبِ الْحَيَاةِ", "uz": "Sizga hayot mushkulotlarida yordam beradigan va yolg'izligingizni yo'qotadigan"}, {"ar": "وَتُؤْنِسُ وَحْدَتَكَ.", "uz": "ayol kerak."}], "full_uz": "Sizga hayot mushkulotlarida yordam beradigan va yolg'izligingizni yo'qotadigan ayol kerak.", "note": null},
{"num": 211, "time": "00:18:20,519 --> 00:18:23,000", "arabic": "رَحِمَ اللَّهُ أُمَّ صَالِحٍ.", "segs": null, "full_uz": "Alloh Solihning onasiga rahmat qilsin.", "note": null},
{"num": 212, "time": "00:18:23,000 --> 00:18:25,380", "arabic": "لَكِنْ يَا أَحْمَدُ هَذِهِ حَالُ الدُّنْيَا.", "segs": null, "full_uz": "Lekin, ey Ahmad, dunyoning holi shu.", "note": null},
{"num": 213, "time": "00:18:25,380 --> 00:18:27,039", "arabic": "أُقَدِّرُ حِرْصَكُمْ عَلَيَّ.", "segs": null, "full_uz": "Menga bo'lgan g'amxo'rligingizni qadrlayman.", "note": null},
{"num": 214, "time": "00:18:27,039 --> 00:18:34,080", "arabic": "وَلَكِنِّي كَوَلَدِي صَالِحٍ، لَا أَوَدُّ أَنْ أَرَى امْرَأَةً أُخْرَى تَأْخُذُ مَكَانَ الْعَبَّاسَةِ رَحِمَهَا اللَّهُ.", "segs": [{"ar": "وَلَكِنِّي كَوَلَدِي صَالِحٍ،", "uz": "Lekin men, o'g'lim Solih kabi,"}, {"ar": "لَا أَوَدُّ أَنْ أَرَى امْرَأَةً أُخْرَى تَأْخُذُ مَكَانَ الْعَبَّاسَةِ رَحِمَهَا اللَّهُ.", "uz": "boshqa bir ayolning Abbasa (Alloh unga rahmat qilsin)ning o'rnini olishini ko'rishni istamayman."}], "full_uz": "Lekin men, o'g'lim Solih kabi, boshqa bir ayolning Abbasa (Alloh unga rahmat qilsin)ning o'rnini olishini ko'rishni istamayman.", "note": null},
{"num": 217, "time": "00:18:34,080 --> 00:18:37,960", "arabic": "وَمَا قَالَ صَالِحٌ ذَلِكَ إِلَّا كَارِهًا.", "segs": null, "full_uz": "Solih buni faqat istamay aytgan edi.", "note": null},
{"num": 218, "time": "00:18:37,960 --> 00:18:43,380", "arabic": "يَا أَحْمَدُ.", "segs": null, "full_uz": "Ey Ahmad.", "note": null},
{"num": 219, "time": "00:18:43,380 --> 00:18:51,900", "arabic": "عَاجِلًا أَمْ آجِلًا سَتُقْدِمُ عَلَى هَذَا الْأَمْرِ، وَقَدْ مَرَّتِ الشُّهُورُ وَأَنْتَ فِي دَارِكَ وَحِيدًا بِلَا أَنِيسٍ وَلَا جَلِيسٍ.", "segs": [{"ar": "عَاجِلًا أَمْ آجِلًا سَتُقْدِمُ عَلَى هَذَا الْأَمْرِ،", "uz": "Erta-yu kech bu ishga qadam qo'yasan,"}, {"ar": "وَقَدْ مَرَّتِ الشُّهُورُ وَأَنْتَ فِي دَارِكَ", "uz": "oylar o'tdi-ku, sen esa uyingda hamsuhbatsiz,"}, {"ar": "وَحِيدًا بِلَا أَنِيسٍ وَلَا جَلِيسٍ.", "uz": "sherigingsiz yolg'iz o'tiribsan."}], "full_uz": "Erta-yu kech bu ishga qadam qo'yasan, oylar o'tdi-ku, sen esa uyingda hamsuhbatsiz, sherigingsiz yolg'iz o'tiribsan.", "note": null},
{"num": 221, "time": "00:18:51,900 --> 00:18:56,380", "arabic": "وَلَا أَظُنُّنِي لَكَ نَاصِحًا فِيمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي يَا ابْنَ أَخِي.", "segs": [{"ar": "وَلَا أَظُنُّنِي لَكَ نَاصِحًا فِيمَا أَنْتَ", "uz": "O'zing mendan yaxshi biladigan narsada senga"}, {"ar": "أَعْلَمُ بِهِ مِنِّي يَا ابْنَ أَخِي.", "uz": "maslahatchi bo'la olmasam kerak, jiyanim."}], "full_uz": "O'zing mendan yaxshi biladigan narsada senga maslahatchi bo'la olmasam kerak, jiyanim.", "note": null},
{"num": 222, "time": "00:18:57,060 --> 00:19:00,440", "arabic": "الْأَيَّامُ تَمُرُّ مُسْرِعَةً يَا عَمِّ.", "segs": null, "full_uz": "Kunlar tez o'tib ketyapti, amaki.", "note": null},
{"num": 223, "time": "00:19:00,440 --> 00:19:06,380", "arabic": "مَا أَجْهَلَ مَنْ غَرَّهُ طُولُ الْأَمَلِ، فَلَمْ يَفْطَنْ إِلَى مَرِّ الْأَيَّامِ وَاللَّيَالِي.", "segs": [{"ar": "مَا أَجْهَلَ مَنْ غَرَّهُ طُولُ الْأَمَلِ،", "uz": "Uzoq umidga aldangan va kunu tunlarning"}, {"ar": "فَلَمْ يَفْطَنْ إِلَى مَرِّ الْأَيَّامِ وَاللَّيَالِي.", "uz": "o'tishini sezmagan kishi naqadar nodondir."}], "full_uz": "Uzoq umidga aldangan va kunu tunlarning o'tishini sezmagan kishi naqadar nodondir.", "note": null},
{"num": 225, "time": "00:19:07,180 --> 00:19:16,460", "arabic": "اللَّهُمَّ لَا تَصْرِفْ قُلُوبَنَا عَنْ طَاعَتِكَ وَلَا تَشْغَلْهَا بِسِوَاكَ. اللَّهُمَّ آمِينَ.", "segs": [{"ar": "اللَّهُمَّ لَا تَصْرِفْ قُلُوبَنَا عَنْ طَاعَتِكَ", "uz": "Ey Alloh, qalblarimizni Senga itoat etishdan burma va ularni Sendan"}, {"ar": "وَلَا تَشْغَلْهَا بِسِوَاكَ. اللَّهُمَّ آمِينَ.", "uz": "boshqa narsa bilan band qilma. Ey Alloh, omin."}], "full_uz": "Ey Alloh, qalblarimizni Senga itoat etishdan burma va ularni Sendan boshqa narsa bilan band qilma. Ey Alloh, omin.", "note": null},
{"num": 229, "time": "00:19:47,380 --> 00:20:14,280", "arabic": "لَقَدْ نَكَّبَ الْمُسْلِمِينَ مِنْ أَهْلِ زِبَطْرَةَ نَكْبَةً عَظِيمَةً، فَقَتَلَ مِنْهُمْ خَلْقًا كَثِيرًا وَأَسَرَ أَعْدَادًا لَا تُحْصَى، وَمَثَّلَ بِمَنْ صَارَ فِي يَدِهِ مِنَ الْمُسْلِمِينَ، فَسَمَلَ أَعْيُنَهُمْ وَجَدَعَ أُنُوفَهُمْ وَقَطَّعَ آذَانَهُمْ، وَارْتَكَبَ مَا لَا يَسْتَطِيعُ الْوَصْفُ أَنْ يَبْلُغَهُ وَلَا الْعَقْلُ أَنْ يَتَخَيَّلَهُ.", "segs": [{"ar": "لَقَدْ نَكَّبَ الْمُسْلِمِينَ مِنْ أَهْلِ زِبَطْرَةَ نَكْبَةً عَظِيمَةً، فَقَتَلَ مِنْهُمْ خَلْقًا كَثِيرًا وَأَسَرَ أَعْدَادًا لَا تُحْصَى", "uz": "U Zibatra ahlidan musulmonlarga katta falokat yetkazdi, ko'pini o'ldirdi va son-sanoqsiz odamni asir oldi"}, {"ar": "وَمَثَّلَ بِمَنْ صَارَ فِي يَدِهِ مِنَ الْمُسْلِمِينَ، فَسَمَلَ أَعْيُنَهُمْ وَجَدَعَ أُنُوفَهُمْ وَقَطَّعَ آذَانَهُمْ", "uz": "qo'liga tushgan musulmonlarni qiynadi — ko'zlarini o'yib, burunlarini kesib, quloqlarini qirqib tashladi"}, {"ar": "وَارْتَكَبَ مَا لَا يَسْتَطِيعُ الْوَصْفُ أَنْ يَبْلُغَهُ وَلَا الْعَقْلُ أَنْ يَتَخَيَّلَهُ", "uz": "va tasvir yeta olmaydigan, aql tasavvur qila olmaydigan ishlarni sodir etdi"}], "full_uz": "U Zibatra ahlidan musulmonlarga katta falokat yetkazdi, ulardan ko'p kishini o'ldirdi va son-sanoqsiz odamni asir oldi, qo'liga tushgan musulmonlarni qiynadi — ko'zlarini o'yib, burunlarini kesib, quloqlarini qirqib tashladi, va tasvir yeta olmaydigan, aql tasavvur qila olmaydigan ishlarni sodir etdi.", "note": null},
{"num": 235, "time": "00:20:17,380 --> 00:20:47,320", "arabic": "إِنَّ دِمَاءَ هَؤُلَاءِ الضَّحَايَا لَا يَحْمِلُ وِزْرَهَا تَوْفِيلُ وَحْدَهُ، إِنَّ وِزْرَهَا هُنَا، أَنَا الْمَسْؤُولُ عَنْ هَؤُلَاءِ الضَّحَايَا أَمَامَ اللَّهِ.", "segs": [{"ar": "إِنَّ دِمَاءَ هَؤُلَاءِ الضَّحَايَا لَا يَحْمِلُ وِزْرَهَا تَوْفِيلُ وَحْدَهُ،", "uz": "Bu qurbonlarning qonining gunohini yolg'iz Tavfil ko'tarmaydi,"}, {"ar": "إِنَّ وِزْرَهَا هُنَا،", "uz": "uning gunohi shu yerda —"}, {"ar": "أَنَا الْمَسْؤُولُ عَنْ هَؤُلَاءِ الضَّحَايَا أَمَامَ اللَّهِ.", "uz": "men bu qurbonlar uchun Alloh oldida mas'ulman."}], "full_uz": "Bu qurbonlarning qonining gunohini yolg'iz Tavfil ko'tarmaydi, uning gunohi shu yerda — men bu qurbonlar uchun Alloh oldida mas'ulman.", "note": null},
{"num": 239, "time": "00:20:47,319 --> 00:20:59,359", "arabic": "إِلَّا مَا أَعْذَرُ لَهُمْ، أَنَا خَلِيفَةُ الْمُسْلِمِينَ، وَأَنَا عَامَّتُهُمْ، وَأَنَا الْمَسْؤُولُ عَنْ حِمَايَتِهِمْ.", "segs": [{"ar": "إِلَّا مَا أَعْذَرُ لَهُمْ، أَنَا خَلِيفَةُ الْمُسْلِمِينَ، وَأَنَا عَامَّتُهُمْ،", "uz": "Ularga uzr aytishga haqqim yo'q, men musulmonlarning xalifasiman, men ularning umumiy vakiliman,"}, {"ar": "وَأَنَا الْمَسْؤُولُ عَنْ حِمَايَتِهِمْ.", "uz": "va ularni himoya qilishga mas'ulman."}], "full_uz": "Ularga uzr aytishga haqqim yo'q, men musulmonlarning xalifasiman, men ularning umumiy vakiliman, va ularni himoya qilishga mas'ulman.", "note": null},
{"num": 243, "time": "00:20:59,359 --> 00:21:12,439", "arabic": "لَا عَاشَ ابْنُ هَارُونَ الرَّشِيدِ إِلَّا مَا يَعْتَذِرُ لِلْأَطْفَالِ وَالشُّيُوخِ وَالنِّسَاءِ.", "segs": [{"ar": "لَا عَاشَ ابْنُ هَارُونَ الرَّشِيدِ إِلَّا مَا يَعْتَذِرُ لِلْأَطْفَالِ", "uz": "Horun ar-Rashidning o'g'li bolalar, chollar va ayollardan uzr"}, {"ar": "وَالشُّيُوخِ وَالنِّسَاءِ.", "uz": "so'ramaguncha yashamasin."}], "full_uz": "Horun ar-Rashidning o'g'li bolalar, chollar va ayollardan uzr so'ramaguncha yashamasin.", "note": null},
{"num": 245, "time": "00:21:12,439 --> 00:21:20,779", "arabic": "لَا عَاشَ الْمُعْتَصِمُ إِنْ لَمْ تَجِدِ الْمُسْلِمَاتُ مَنْ يَحْمِي أَعْرَاضَهُنَّ.", "segs": [{"ar": "لَا عَاشَ الْمُعْتَصِمُ إِنْ لَمْ", "uz": "Musulmon ayollar o'z or-nomuslarini himoya qiladigan kimsani topmasa,"}, {"ar": "تَجِدِ الْمُسْلِمَاتُ مَنْ يَحْمِي أَعْرَاضَهُنَّ.", "uz": "Mu'tasim yashamasin."}], "full_uz": "Musulmon ayollar o'z or-nomuslarini himoya qiladigan kimsani topmasa, Mu'tasim yashamasin.", "note": null},
{"num": 247, "time": "00:21:20,779 --> 00:21:27,939", "arabic": "لَقَدْ أَخْبَرَنِي هَذَا الرَّجُلُ يَا مَوْلَايَ أَمْرًا عَجَبًا أَنْ تَسْمَعَهُ.", "segs": [{"ar": "لَقَدْ أَخْبَرَنِي هَذَا الرَّجُلُ يَا", "uz": "Bu odam menga sizga eshittirish uchun"}, {"ar": "مَوْلَايَ أَمْرًا عَجَبًا أَنْ تَسْمَعَهُ.", "uz": "ajoyib bir voqeani aytib berdi, xo'jayinim."}], "full_uz": "Bu odam menga sizga eshittirish uchun ajoyib bir voqeani aytib berdi, xo'jayinim.", "note": null},
{"num": 249, "time": "00:21:27,939 --> 00:21:31,000", "arabic": "قُلْ إِنِّي أَسْمَعُ.", "segs": null, "full_uz": "Ayt, quloq solyapman.", "note": null},
{"num": 250, "time": "00:21:31,000 --> 00:21:45,079", "arabic": "يَا مَوْلَايَ، لَقَدْ عَذَّبَ الرُّومُ امْرَأَةً اسْمُهَا شَرَاتُ الْعَلَوِيَّةُ، وَسَاقُوهَا سَبِيًّا، وَنَكَّلُوا بِهَا، وَقَدْ صَرَخَتْ بِأَعْلَى صَوْتِهَا: وَامُعْتَصِمَاهُ!", "segs": [{"ar": "يَا مَوْلَايَ، لَقَدْ عَذَّبَ الرُّومُ امْرَأَةً اسْمُهَا شَرَاتُ الْعَلَوِيَّةُ،", "uz": "Xo'jayinim, Rumliklar Sharat al-Alaviyya ismli bir ayolni qiynashdi,"}, {"ar": "وَسَاقُوهَا سَبِيًّا، وَنَكَّلُوا بِهَا،", "uz": "uni asirlikka olib ketishdi va unga zulm qilishdi,"}, {"ar": "وَقَدْ صَرَخَتْ بِأَعْلَى صَوْتِهَا: وَامُعْتَصِمَاهُ!", "uz": "u esa baland ovoz bilan: \"Voy, Mu'tasim!\" deb faryod chekdi."}], "full_uz": "Xo'jayinim, Rumliklar Sharat al-Alaviyya ismli bir ayolni qiynashdi, uni asirlikka olib ketishdi va unga zulm qilishdi, u esa baland ovoz bilan: \"Voy, Mu'tasim!\" deb faryod chekdi.", "note": "\"وا معتصماه\" — tarixiy rivoyatga ko'ra, Rumliklar asir olgan bir ayolning bu faryodi Mu'tasimning Amuriya yurishiga turtki bo'lgan mashhur voqea."},
{"num": 256, "time": "00:21:45,079 --> 00:22:11,279", "arabic": "قَدْ أَرْسَلَتْ أُمُّ الْفَضْلِ إِلَى ابْنِ عَمِّنَا مُحَمَّدِ بْنِ رَيْحَانَ الشَّيْبَانِيِّ كَمَا أَمَرْتَ يَا أَبِي، وَقَالَتْ إِنَّهَا رَأَتْ أُخْتَيَّ عَصْمَاءَ وَرَيْحَانَةَ، وَأَنَّ كِلَا الْمَرْأَتَيْنِ لَا مَانِعَ لَدَيْهَا فِي الزَّوَاجِ.", "segs": [{"ar": "قَدْ أَرْسَلَتْ أُمُّ الْفَضْلِ إِلَى ابْنِ عَمِّنَا مُحَمَّدِ بْنِ رَيْحَانَ الشَّيْبَانِيِّ كَمَا أَمَرْتَ يَا أَبِي،", "uz": "Umm al-Fazl siz buyurganingizdek amakivachchamiz Muhammad ibn Rayhon ash-Shayboniyga xabar yubordi, dadajon,"}, {"ar": "وَقَالَتْ إِنَّهَا رَأَتْ أُخْتَيَّ عَصْمَاءَ وَرَيْحَانَةَ،", "uz": "va singillarim Asmo va Rayhonani ko'rganini,"}, {"ar": "وَأَنَّ كِلَا الْمَرْأَتَيْنِ لَا مَانِعَ لَدَيْهَا فِي الزَّوَاجِ.", "uz": "ikkala ayolning ham turmushga chiqishga qarshiligi yo'qligini aytdi."}], "full_uz": "Umm al-Fazl siz buyurganingizdek amakivachchamiz Muhammad ibn Rayhon ash-Shayboniyga xabar yubordi, dadajon, va singillarim Asmo va Rayhonani ko'rganini, ikkala ayolning ham turmushga chiqishga qarshiligi yo'qligini aytdi.", "note": null},
{"num": 259, "time": "00:22:11,279 --> 00:22:14,980", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا وَلَدِي وَرَحِمَ اللَّهُ أُمَّكَ الْعَبَّاسَةَ.", "segs": null, "full_uz": "Alloh senga barakot bersin, o'g'lim, va onang Abbasaga rahmat qilsin.", "note": null},
{"num": 260, "time": "00:22:14,980 --> 00:22:20,819", "arabic": "وَقَالَتْ أُمُّ الْفَضْلِ إِنَّ عَصْمَاءَ ابْنَةَ رَيْحَانَ هِيَ الْأَنْسَبُ وَقَدْ وَقَعَ اخْتِيَارُهَا عَلَيْهَا.", "segs": [{"ar": "وَقَالَتْ أُمُّ الْفَضْلِ إِنَّ عَصْمَاءَ ابْنَةَ رَيْحَانَ هِيَ الْأَنْسَبُ", "uz": "Umm al-Fazl Rayhonning qizi Asmo eng mos ekanini aytdi"}, {"ar": "وَقَدْ وَقَعَ اخْتِيَارُهَا عَلَيْهَا.", "uz": "va tanlovi unga tushdi."}], "full_uz": "Umm al-Fazl Rayhonning qizi Asmo eng mos ekanini aytdi va tanlovi unga tushdi.", "note": null},
{"num": 261, "time": "00:22:20,819 --> 00:22:29,140", "arabic": "وَلَكِنْ يَا وَلَدِي سَمِعْتُ أَنَّ رَيْحَانَةَ أَشَدُّ دِينًا مِنْ أُخْتِهَا عَصْمَاءَ.", "segs": [{"ar": "وَلَكِنْ يَا", "uz": "Lekin, o'g'lim,"}, {"ar": "وَلَدِي سَمِعْتُ أَنَّ رَيْحَانَةَ أَشَدُّ دِينًا مِنْ أُخْتِهَا عَصْمَاءَ.", "uz": "eshitishimcha, Rayhona dinda singlisi Asmodan ustunroq ekan."}], "full_uz": "Lekin, o'g'lim, eshitishimcha, Rayhona dinda singlisi Asmodan ustunroq ekan.", "note": null},
{"num": 262, "time": "00:22:29,140 --> 00:22:35,920", "arabic": "هَذَا صَحِيحٌ يَا أَبِي، وَلَكِنْ أَعْذِرْنِي، رَيْحَانَةُ عَوْرَاءُ وَلَيْسَتْ بِجَمَالِ أُخْتِهَا.", "segs": [{"ar": "هَذَا صَحِيحٌ يَا أَبِي، وَلَكِنْ أَعْذِرْنِي،", "uz": "Bu to'g'ri, dadajon, lekin meni ma'zur tuting,"}, {"ar": "رَيْحَانَةُ عَوْرَاءُ وَلَيْسَتْ بِجَمَالِ أُخْتِهَا.", "uz": "Rayhona bir ko'zi ko'r va singlisi qadar chiroyli emas."}], "full_uz": "Bu to'g'ri, dadajon, lekin meni ma'zur tuting, Rayhona bir ko'zi ko'r va singlisi qadar chiroyli emas.", "note": null},
{"num": 263, "time": "00:22:39,980 --> 00:22:44,099", "arabic": "وَهَلْ تَرَانِي مِمَّنْ يَبْحَثُونَ عَنِ الْجَمَالِ يَا ابْنَ الْعَبَّاسَةِ؟", "segs": null, "full_uz": "Meni go'zallik izlaydiganlardan deb bilyapsanmi, Abbasaning o'g'li?", "note": null},
{"num": 264, "time": "00:22:44,099 --> 00:22:48,519", "arabic": "يَا أَبِي، كِلْتَا الْمَرْأَتَيْنِ مُنَاسِبَةٌ لَكَ إِنْ شَاءَ اللَّهُ.", "segs": null, "full_uz": "Dadajon, inshaalloh, ikkala ayol ham sizga mos.", "note": null},
{"num": 265, "time": "00:22:48,519 --> 00:22:54,259", "arabic": "وَإِنْ تَكُنْ رَيْحَانَةُ تَفُوقُ أُخْتَهَا عَصْمَاءَ تَدَيُّنًا، فَإِنَّ عَصْمَاءَ لَا تَقِلُّ عَنْهَا.", "segs": [{"ar": "وَإِنْ تَكُنْ رَيْحَانَةُ تَفُوقُ أُخْتَهَا عَصْمَاءَ تَدَيُّنًا،", "uz": "Agar Rayhona dindorlikda singlisi Asmodan ustun bo'lsa ham,"}, {"ar": "فَإِنَّ عَصْمَاءَ لَا تَقِلُّ عَنْهَا.", "uz": "Asmo undan kam emas."}], "full_uz": "Agar Rayhona dindorlikda singlisi Asmodan ustun bo'lsa ham, Asmo undan kam emas.", "note": null},
{"num": 267, "time": "00:22:54,259 --> 00:22:56,519", "arabic": "ثُمَّ إِنَّ عَصْمَاءَ صَحِيحَةٌ مُعَافَاةٌ.", "segs": null, "full_uz": "Bundan tashqari, Asmo sog'lom va tuzuk.", "note": null},
{"num": 268, "time": "00:22:56,519 --> 00:23:08,599", "arabic": "صِحَّةُ الْقَلْبِ أَهَمُّ مِنْ صِحَّةِ الْبَدَنِ يَا وَلَدِي، وَالْمُعَافَى مَنْ عُوفِيَ بِدِينِهِ، مَاذَا تَعَلَّمْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَاظْفَرْ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ.", "segs": [{"ar": "صِحَّةُ الْقَلْبِ أَهَمُّ مِنْ صِحَّةِ الْبَدَنِ يَا وَلَدِي،", "uz": "Qalb sog'lig'i tan sog'lig'idan muhimroq, o'g'lim,"}, {"ar": "وَالْمُعَافَى مَنْ عُوفِيَ بِدِينِهِ،", "uz": "tuzuk kishi — dinida tuzuk bo'lgan kishidir."}, {"ar": "مَاذَا تَعَلَّمْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟", "uz": "Rasululloh (sav)dan nima o'rgangansan?"}, {"ar": "فَاظْفَرْ بِذَاتِ الدِّينِ تَرِبَتْ يَدَاكَ.", "uz": "\"Dindor ayolni tanla, qo'llaring tuproqqa to'lsin (aks holda kambag'al qolasan)\"."}], "full_uz": "Qalb sog'lig'i tan sog'lig'idan muhimroq, o'g'lim, tuzuk kishi — dinida tuzuk bo'lgan kishidir. Rasululloh (sav)dan nima o'rgangansan? \"Dindor ayolni tanla, qo'llaring tuproqqa to'lsin (aks holda kambag'al qolasan)\".", "note": "\"فاظفر بذات الدين تربت يداك\" — turmush o'rtoq tanlash haqidagi mashhur hadis (Buxoriy, Muslim)."},
{"num": 272, "time": "00:23:08,599 --> 00:23:10,319", "arabic": "بَارَكَ اللَّهُ فِيكَ.", "segs": null, "full_uz": "Alloh senga barakot bersin.", "note": null},
{"num": 273, "time": "00:23:14,099 --> 00:23:21,759", "arabic": "لَكِنَّكَ قُلْتَ لِي إِنَّكَ تَرَكْتَهُمْ وَلَنْ تَعُودَ إِلَيْهِمْ.", "segs": null, "full_uz": "Lekin sen menga ularni tark etganingni va ularga qaytmasligingni aytgan eding.", "note": null},
{"num": 275, "time": "00:23:21,759 --> 00:23:23,719", "arabic": "تَرَكْتُهُمْ.", "segs": null, "full_uz": "Ularni tark etdim.", "note": null},
{"num": 276, "time": "00:23:23,719 --> 00:23:29,439", "arabic": "وَلَكِنِّي لَمْ أَتْرُكِ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَنُصْرَةَ الْمَظْلُومِينَ يَا فَوْزُ.", "segs": [{"ar": "وَلَكِنِّي لَمْ أَتْرُكِ الْجِهَادَ فِي سَبِيلِ اللَّهِ", "uz": "Lekin men Alloh yo'lidagi jihodni va mazlumlarga yordam berishni tark etmadim,"}, {"ar": "وَنُصْرَةَ الْمَظْلُومِينَ يَا فَوْزُ.", "uz": "ey Fawz."}], "full_uz": "Lekin men Alloh yo'lidagi jihodni va mazlumlarga yordam berishni tark etmadim, ey Fawz.", "note": null},
{"num": 277, "time": "00:23:29,439 --> 00:23:37,740", "arabic": "اسْتَلَّ أَمِيرُ الْمُؤْمِنِينَ سَيْفَهُ لِقِتَالِ الْكُفَّارِ، فَوَجَدَنِي مَعَهُ وَإِنْ كُنْتُ أَزْحَفُ عَلَى رُكْبَتَيَّ.", "segs": [{"ar": "اسْتَلَّ أَمِيرُ الْمُؤْمِنِينَ سَيْفَهُ لِقِتَالِ الْكُفَّارِ،", "uz": "Mo'minlar amiri kofirlarga qarshi qilichini sug'urganida,"}, {"ar": "فَوَجَدَنِي مَعَهُ وَإِنْ كُنْتُ أَزْحَفُ عَلَى رُكْبَتَيَّ.", "uz": "meni o'zi bilan birga topdi, garchi tizzalarim ustida sudralib borsam ham."}], "full_uz": "Mo'minlar amiri kofirlarga qarshi qilichini sug'urganida, meni o'zi bilan birga topdi, garchi tizzalarim ustida sudralib borsam ham.", "note": null},
{"num": 279, "time": "00:23:37,740 --> 00:23:48,400", "arabic": "إِنَّمَا تَرَكْتُهُمْ حِينَ ظَلَمُوا النَّاسَ وَعَذَّبُوا إِمَامَ الْمُسْلِمِينَ أَحْمَدَ بْنَ حَنْبَلٍ.", "segs": [{"ar": "إِنَّمَا تَرَكْتُهُمْ حِينَ ظَلَمُوا النَّاسَ", "uz": "Men ularni faqat odamlarga zulm qilib,"}, {"ar": "وَعَذَّبُوا إِمَامَ الْمُسْلِمِينَ أَحْمَدَ بْنَ حَنْبَلٍ.", "uz": "musulmonlar imomi Ahmad ibn Hanbalni qiynaganlarida tark etgan edim."}], "full_uz": "Men ularni faqat odamlarga zulm qilib, musulmonlar imomi Ahmad ibn Hanbalni qiynaganlarida tark etgan edim.", "note": null},
{"num": 281, "time": "00:23:48,400 --> 00:23:56,099", "arabic": "أَمَّا وَهُمْ يُرِيدُونَ الْخُرُوجَ لِقِتَالِ الْكُفَّارِ، فَوَاللَّهِ لَنْ أَتَقَاعَسَ مَا نَبَضَ بِي عِرْقُ دَمٍ.", "segs": [{"ar": "أَمَّا وَهُمْ يُرِيدُونَ الْخُرُوجَ لِقِتَالِ الْكُفَّارِ،", "uz": "Ular kofirlarga qarshi chiqmoqchi bo'lgan ekan,"}, {"ar": "فَوَاللَّهِ لَنْ أَتَقَاعَسَ مَا نَبَضَ بِي عِرْقُ دَمٍ.", "uz": "vallohi, tomirimda qon urib turar ekan, orqada qolmayman."}], "full_uz": "Ular kofirlarga qarshi chiqmoqchi bo'lgan ekan, vallohi, tomirimda qon urib turar ekan, orqada qolmayman.", "note": null},
{"num": 283, "time": "00:23:56,099 --> 00:24:07,039", "arabic": "وَلَكِنَّكَ أَفْنَيْتَ حَيَاتَكَ فِي الْجِهَادِ ضِدَّ الْكُفَّارِ، وَكَانَ جَزَاؤُكَ أَنْ تُؤَخَّرَ وَيُقَدَّمَ غَيْرُكَ فِي دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ.", "segs": [{"ar": "وَلَكِنَّكَ أَفْنَيْتَ حَيَاتَكَ فِي الْجِهَادِ ضِدَّ الْكُفَّارِ،", "uz": "Lekin sen umringni kofirlarga qarshi jihodda sarfladingu,"}, {"ar": "وَكَانَ جَزَاؤُكَ أَنْ تُؤَخَّرَ", "uz": "mo'minlar amiri davlatida senga bo'lgan mukofot — orqaga surilib,"}, {"ar": "وَيُقَدَّمَ غَيْرُكَ فِي دَوْلَةِ أَمِيرِ الْمُؤْمِنِينَ.", "uz": "boshqa birov oldinga qo'yilishi bo'ldi."}], "full_uz": "Lekin sen umringni kofirlarga qarshi jihodda sarfladingu, mo'minlar amiri davlatida senga bo'lgan mukofot — orqaga surilib, boshqa birov oldinga qo'yilishi bo'ldi.", "note": null},
{"num": 286, "time": "00:24:07,039 --> 00:24:17,960", "arabic": "التَّقْدِيمُ وَالتَّأْخِيرُ فِي الْآخِرَةِ لَا فِي الدُّنْيَا يَا فَوْزُ، وَهَذَا جِهَادُ دَفْعٍ وَوَاجِبٌ عَلَى كُلِّ مَنْ نَطَقَ بِالشَّهَادَتَيْنِ.", "segs": [{"ar": "التَّقْدِيمُ", "uz": "Oldinga"}, {"ar": "وَالتَّأْخِيرُ فِي الْآخِرَةِ لَا فِي الدُّنْيَا يَا فَوْزُ،", "uz": "qo'yish va orqaga surish oxiratda bo'ladi, dunyoda emas, ey Fawz,"}, {"ar": "وَهَذَا جِهَادُ دَفْعٍ وَوَاجِبٌ عَلَى كُلِّ مَنْ نَطَقَ بِالشَّهَادَتَيْنِ.", "uz": "va bu himoya jihodi bo'lib, ikki kalima-shahodat aytgan har bir kishiga farzdir."}], "full_uz": "Oldinga qo'yish va orqaga surish oxiratda bo'ladi, dunyoda emas, ey Fawz, va bu himoya jihodi bo'lib, ikki kalima-shahodat aytgan har bir kishiga farzdir.", "note": null},
{"num": 288, "time": "00:24:37,039 --> 00:24:56,180", "arabic": "إِنْ قَدَّرَ اللَّهُ لِي أَنْ أَعُودَ، فَقَدْ نِلْتُ مَا تَتَمَنَّيْنَ، وَإِنْ أَكْرَمَنِيَ اللَّهُ بِالشَّهَادَةِ، فَقَدْ نِلْتُ مَا أَتَمَنَّى.", "segs": [{"ar": "إِنْ قَدَّرَ اللَّهُ لِي أَنْ أَعُودَ، فَقَدْ نِلْتُ مَا تَتَمَنَّيْنَ،", "uz": "Agar Alloh menga qaytishni taqdir qilsa, sen istagan narsaga erishgan bo'laman,"}, {"ar": "وَإِنْ أَكْرَمَنِيَ اللَّهُ بِالشَّهَادَةِ،", "uz": "agar Alloh meni shahodat bilan mukarram qilsa,"}, {"ar": "فَقَدْ نِلْتُ مَا أَتَمَنَّى.", "uz": "o'zim istagan narsaga erishgan bo'laman."}], "full_uz": "Agar Alloh menga qaytishni taqdir qilsa, sen istagan narsaga erishgan bo'laman, agar Alloh meni shahodat bilan mukarram qilsa, o'zim istagan narsaga erishgan bo'laman.", "note": null},
{"num": 292, "time": "00:24:56,180 --> 00:25:03,559", "arabic": "اغْفِرِي تَقْصِيرِي مَعَكِ، وَابْقَيْ كَمَا عَهِدْتُكِ.", "segs": null, "full_uz": "Senga qilgan kamchiligimni kechir, va bilganimdek qolaver.", "note": null},
{"num": 298, "time": "00:26:33,559 --> 00:26:39,299", "arabic": "السَّلَامُ عَلَيْكُمْ يَا مَوْلَايَ.", "segs": null, "full_uz": "Assalomu alaykum, xo'jayinim.", "note": null},
{"num": 299, "time": "00:26:39,299 --> 00:26:41,059", "arabic": "السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Mo'minlar amiriga salom bo'lsin.", "note": null},
{"num": 300, "time": "00:26:41,059 --> 00:26:42,339", "arabic": "عَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Alaykum assalom.", "note": null},
{"num": 301, "time": "00:26:42,339 --> 00:26:47,379", "arabic": "هَذَا هُوَ الْقَاضِي الَّذِي أَمَرْتَ بِإِحْضَارِهِ، وَهَؤُلَاءِ هُمُ الشُّهُودُ.", "segs": null, "full_uz": "Mana bu siz olib kelishni buyurgan qozi, va mana bular guvohlar.", "note": null},
{"num": 303, "time": "00:26:47,379 --> 00:26:49,740", "arabic": "تَفَضَّلْ أَيُّهَا الْقَاضِي.", "segs": null, "full_uz": "Marhamat, ey qozi.", "note": null},
{"num": 304, "time": "00:26:49,740 --> 00:27:01,619", "arabic": "أَمْرُ أَمِيرِ الْمُؤْمِنِينَ، اكْتُبْ.", "segs": null, "full_uz": "Mo'minlar amirining buyrug'i, yoz.", "note": null},
{"num": 306, "time": "00:27:01,619 --> 00:27:04,059", "arabic": "لَبَّيْكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Labbay, xo'jayinim.", "note": null},
{"num": 307, "time": "00:27:04,059 --> 00:27:14,759", "arabic": "أَنَا الْمُعْتَصِمُ ابْنُ هَارُونَ الرَّشِيدِ.", "segs": null, "full_uz": "Men Horun ar-Rashidning o'g'li Mu'tasimman.", "note": null},
{"num": 309, "time": "00:27:14,759 --> 00:27:22,399", "arabic": "أُشْهِدُ اللَّهَ وَأُشْهِدُ الْحُضُورَ.", "segs": null, "full_uz": "Allohni va bu yerdagilarni guvoh qilaman.", "note": null},
{"num": 311, "time": "00:27:22,399 --> 00:27:43,800", "arabic": "أَنَّ مَا أَمْلِكُهُ مِنْ ضِيَاعٍ وَمَالٍ، ثُلُثُهُ صَدَقَةٌ لِوَجْهِ اللَّهِ، وَثُلُثُهُ لِأَوْلَادِي، وَثُلُثُهُ لِمَوَالِيَّ.", "segs": [{"ar": "أَنَّ مَا أَمْلِكُهُ مِنْ ضِيَاعٍ وَمَالٍ، ثُلُثُهُ صَدَقَةٌ لِوَجْهِ اللَّهِ،", "uz": "Egalik qilgan yer-mulk va boyligimning uchdan bir qismi Alloh yuzi uchun sadaqa, uchdan bir qismi farzandlarimga,"}, {"ar": "وَثُلُثُهُ لِأَوْلَادِي، وَثُلُثُهُ لِمَوَالِيَّ.", "uz": "uchdan bir qismi esa mavlolarimga tegishlidir."}], "full_uz": "Egalik qilgan yer-mulk va boyligimning uchdan bir qismi Alloh yuzi uchun sadaqa, uchdan bir qismi farzandlarimga, uchdan bir qismi esa mavlolarimga tegishlidir.", "note": null},
{"num": 315, "time": "00:27:43,800 --> 00:27:51,100", "arabic": "هَلْ تَشْهَدُونَ؟", "segs": null, "full_uz": "Guvohlik berasizlarmi?", "note": null},
{"num": 316, "time": "00:27:51,100 --> 00:27:52,420", "arabic": "نَعَمْ نَشْهَدُ.", "segs": null, "full_uz": "Ha, guvohlik beramiz.", "note": null},
{"num": 317, "time": "00:27:52,420 --> 00:27:54,720", "arabic": "عَلَى بَرَكَةِ اللَّهِ.", "segs": null, "full_uz": "Allohning barakoti bilan.", "note": null},
{"num": 318, "time": "00:27:54,720 --> 00:27:57,160", "arabic": "لَا فَجَعَنَا اللَّهُ بِكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Alloh bizni sizdan judo qilmasin, xo'jayinim.", "note": null},
{"num": 319, "time": "00:27:57,160 --> 00:28:04,480", "arabic": "سُبْحَانَ الْحَيِّ الَّذِي بِيَدِهِ الْمَوْتُ وَالْحَيَاةُ، كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ.", "segs": [{"ar": "سُبْحَانَ الْحَيِّ الَّذِي بِيَدِهِ الْمَوْتُ وَالْحَيَاةُ،", "uz": "O'lim va hayot qo'lida bo'lgan Tirik Zot pokdir,"}, {"ar": "كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ.", "uz": "har bir jon o'limni totuvchidir."}], "full_uz": "O'lim va hayot qo'lida bo'lgan Tirik Zot pokdir, har bir jon o'limni totuvchidir.", "note": "Qur'on, Oli Imron surasi, 185-oyat."},
{"num": 321, "time": "00:28:04,480 --> 00:28:07,640", "arabic": "عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "segs": null, "full_uz": "Payg'ambar (sollallohu alayhi va sallam)dan rivoyat qilinadi.", "note": null},
{"num": 323, "time": "00:28:09,540 --> 00:28:33,600", "arabic": "إِنَّمَا الْإِمَامُ جُنَّةٌ يُقَاتَلُ مِنْ وَرَائِهِ وَيُتَّقَى بِهِ، فَإِنْ أَمَرَ بِتَقْوَى وَعَدْلٍ فَإِنَّ لَهُ بِذَلِكَ أَجْرًا، وَإِنْ أَمَرَ بِغَيْرِ ذَلِكَ فَإِنَّ عَلَيْهِ مِنْهَا.", "segs": [{"ar": "إِنَّمَا الْإِمَامُ جُنَّةٌ يُقَاتَلُ مِنْ", "uz": "Albatta, imom (rahbar) qalqondir,"}, {"ar": "وَرَائِهِ وَيُتَّقَى بِهِ،", "uz": "uning ortidan urush qilinadi va u bilan"}, {"ar": "فَإِنْ أَمَرَ بِتَقْوَى وَعَدْلٍ فَإِنَّ لَهُ بِذَلِكَ أَجْرًا،", "uz": "(dushmandan) himoyalanadi. Agar u taqvo va adolatga buyursa, unga shu uchun ajr bor,"}, {"ar": "وَإِنْ أَمَرَ بِغَيْرِ ذَلِكَ فَإِنَّ عَلَيْهِ مِنْهَا.", "uz": "agar boshqa narsaga buyursa, uning gunohi o'ziga bo'ladi."}], "full_uz": "Albatta, imom (rahbar) qalqondir, uning ortidan urush qilinadi va u bilan (dushmandan) himoyalanadi. Agar u taqvo va adolatga buyursa, unga shu uchun ajr bor, agar boshqa narsaga buyursa, uning gunohi o'ziga bo'ladi.", "note": "Sahih Muslimdagi hadis."},
{"num": 328, "time": "00:28:33,600 --> 00:28:44,120", "arabic": "اللَّهُمَّ انْصُرْ عَبْدَكَ الْمُعْتَصِمَ عَلَى الْقَوْمِ الظَّالِمِينَ.", "segs": null, "full_uz": "Ey Alloh, bandang Mu'tasimga zolim qavm ustidan g'alaba ber.", "note": null},
{"num": 329, "time": "00:28:44,120 --> 00:28:50,060", "arabic": "إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ.", "segs": null, "full_uz": "Agar siz Allohga yordam bersangiz, U ham sizga yordam beradi va oyoqlaringizni mustahkam qiladi.", "note": "Qur'on, Muhammad surasi, 7-oyat."},
{"num": 330, "time": "00:28:50,060 --> 00:28:52,019", "arabic": "بُورِكْتَ.", "segs": null, "full_uz": "Barakotli bo'lasan.", "note": null},
{"num": 331, "time": "00:28:52,019 --> 00:28:54,600", "arabic": "وَأَنْتَ أَيُّهَا الْوَاثِقُ.", "segs": null, "full_uz": "Sen ham, ey Vosiq.", "note": null},
{"num": 332, "time": "00:28:54,599 --> 00:28:56,299", "arabic": "لَبَّيْكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Labbay, xo'jayinim.", "note": null},
{"num": 333, "time": "00:28:56,299 --> 00:30:07,220", "arabic": "اسْمَعْنِي يَا وَلَدِي، إِنِّي أُوصِيكَ وَصِيَّةَ مَوَدَّةٍ: الْمُسْلِمُونَ أَمَانَةٌ بَيْنَ يَدَيْكَ، دِينُهُمْ، دِمَاؤُهُمْ، أَمْوَالُهُمْ، أَعْرَاضُهُمْ. أَطِعِ اللَّهَ وَرَسُولَهُ، كُنْ أَبًا فَيَكُونَ لَكَ أَبْنَاءٌ بَرَرَةٌ، وَاعْلَمْ أَنَّكَ عَنْهُمْ مَسْؤُولٌ، فَاللَّهُ سَائِلٌ كُلَّ مَوْلَاهُ، كَمَا قَالَ نَبِيُّكَ وَمَوْلَاكَ وَابْنُ عَمِّكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهَ اللَّهَ فِي الْمُسْلِمِينَ.", "segs": [{"ar": "اسْمَعْنِي يَا وَلَدِي، إِنِّي أُوصِيكَ وَصِيَّةَ مَوَدَّةٍ: الْمُسْلِمُونَ أَمَانَةٌ بَيْنَ يَدَيْكَ", "uz": "Meni tingla, o'g'lim, senga muhabbat vasiyatini qilaman: musulmonlar sening qo'lingdagi omonatdir"}, {"ar": "دِينُهُمْ، دِمَاؤُهُمْ، أَمْوَالُهُمْ، أَعْرَاضُهُمْ. أَطِعِ اللَّهَ وَرَسُولَهُ", "uz": "ularning dini, qonlari, mollari, or-nomuslari. Allohga va Uning Rasuliga itoat qil"}, {"ar": "كُنْ أَبًا فَيَكُونَ لَكَ أَبْنَاءٌ بَرَرَةٌ، وَاعْلَمْ أَنَّكَ عَنْهُمْ مَسْؤُولٌ", "uz": "ota bo'l, shunda senga solih farzandlar bo'ladi, va bilki, sen ular uchun mas'ulsan"}, {"ar": "فَاللَّهُ سَائِلٌ كُلَّ مَوْلَاهُ، كَمَا قَالَ نَبِيُّكَ وَمَوْلَاكَ وَابْنُ عَمِّكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "chunki Alloh har bir mavlosini so'roq qiladi, xuddi payg'ambaring, mavloing va amakivachchang Rasululloh aytganidek"}, {"ar": "اللَّهَ اللَّهَ فِي الْمُسْلِمِينَ", "uz": "\"Allohdan qo'rqinglar, Allohdan qo'rqinglar, musulmonlar haqida!\""}], "full_uz": "Meni tingla, o'g'lim, senga muhabbat vasiyatini qilaman: musulmonlar sening qo'lingdagi omonatdir — ularning dini, qonlari, mollari, or-nomuslari. Allohga va Uning Rasuliga itoat qil, ota bo'l, shunda senga solih farzandlar bo'ladi, va bilki, sen ular uchun mas'ulsan, chunki Alloh har bir mavlosini so'roq qiladi, xuddi payg'ambaring, mavloing va amakivachchang Rasululloh (sollallohu alayhi va sallam) aytganidek: \"Allohdan qo'rqinglar, Allohdan qo'rqinglar, musulmonlar haqida!\"", "note": null},
{"num": 353, "time": "00:30:07,220 --> 00:30:14,280", "arabic": "أَيُّهَا الْقَوْمُ، الْمُسْلِمُونَ أَمَانَةٌ فِي أَعْنَاقِكُمْ.", "segs": null, "full_uz": "Ey qavm, musulmonlar sizning bo'yningizdagi omonatdir.", "note": null},
{"num": 355, "time": "00:30:14,280 --> 00:30:21,360", "arabic": "أَعَزَّ اللَّهُ الْمُسْلِمِينَ بِنَصْرِهِ يَا أَمِيرَ الْمُؤْمِنِينَ، وَأَعَادَكَ إِلَيْنَا سَالِمًا غَانِمًا.", "segs": [{"ar": "أَعَزَّ اللَّهُ الْمُسْلِمِينَ بِنَصْرِهِ يَا أَمِيرَ الْمُؤْمِنِينَ،", "uz": "Alloh musulmonlarni O'z nusrati bilan aziz qilsin, ey mo'minlar amiri,"}, {"ar": "وَأَعَادَكَ إِلَيْنَا سَالِمًا غَانِمًا.", "uz": "va sizni bizga sog'-omon va g'animat bilan qaytarsin."}], "full_uz": "Alloh musulmonlarni O'z nusrati bilan aziz qilsin, ey mo'minlar amiri, va sizni bizga sog'-omon va g'animat bilan qaytarsin.", "note": null},
{"num": 358, "time": "00:30:51,140 --> 00:30:52,980", "arabic": "إِلَى النَّصْرِ أَيُّهَا الْمُسْلِمُونَ!", "segs": null, "full_uz": "G'alabaga, ey musulmonlar!", "note": null},
{"num": 359, "time": "00:30:52,980 --> 00:30:55,240", "arabic": "اللَّهُ أَكْبَرُ.", "segs": null, "full_uz": "Allohu akbar.", "note": null},
{"num": 360, "time": "00:30:55,240 --> 00:31:11,880", "arabic": "السَّلَامُ عَلَيْكُمْ يَا مَوْلَايَ.", "segs": null, "full_uz": "Assalomu alaykum, xo'jayinim.", "note": null},
{"num": 361, "time": "00:31:11,880 --> 00:31:14,640", "arabic": "وَعَلَيْكَ السَّلَامُ يَا سَعِيدُ.", "segs": null, "full_uz": "Va alaykum assalom, ey Sa'id.", "note": null},
{"num": 362, "time": "00:31:14,640 --> 00:31:15,980", "arabic": "طَلَبْتَنِي يَا مَوْلَايَ؟", "segs": null, "full_uz": "Meni chaqirdingizmi, xo'jayinim?", "note": null},
{"num": 363, "time": "00:31:15,980 --> 00:31:17,320", "arabic": "أَجَلْ.", "segs": null, "full_uz": "Ha.", "note": null},
{"num": 364, "time": "00:31:17,320 --> 00:31:21,980", "arabic": "أُرِيدُكَ أَنْ تَحْمِلَ هَذِهِ الرِّسَالَةَ إِلَى الْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ.", "segs": [{"ar": "أُرِيدُكَ أَنْ تَحْمِلَ هَذِهِ الرِّسَالَةَ", "uz": "Sendan bu xatni Imom Ahmad"}, {"ar": "إِلَى الْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ.", "uz": "ibn Hanbalga olib borishingni istayman."}], "full_uz": "Sendan bu xatni Imom Ahmad ibn Hanbalga olib borishingni istayman.", "note": null},
{"num": 366, "time": "00:31:21,980 --> 00:31:24,400", "arabic": "تَعْرِفُ بَيْتَهُ، آهْ؟", "segs": null, "full_uz": "Uyini bilasan-a?", "note": null},
{"num": 367, "time": "00:31:25,320 --> 00:31:28,560", "arabic": "وَأَيُّنَا يَجْهَلُ بَيْتَ الْإِمَامِ أَبِي عَبْدِ اللَّهِ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Qaysimiz Imom Abu Abdullohning uyini bilmaymiz, xo'jayinim?", "note": null},
{"num": 369, "time": "00:31:28,560 --> 00:31:35,080", "arabic": "لَوْ سَمِعَكَ مَوْلَاكَ الْوَاثِقُ تَقُولُ ذَلِكَ، لَمْ يَكْفِ قَطْعُ لِسَانِكَ يَا سَعِيدُ.", "segs": [{"ar": "لَوْ سَمِعَكَ مَوْلَاكَ الْوَاثِقُ تَقُولُ ذَلِكَ،", "uz": "Agar xo'jayining Vosiq seni buni aytayotganingni eshitsa,"}, {"ar": "لَمْ يَكْفِ قَطْعُ لِسَانِكَ يَا سَعِيدُ.", "uz": "tilingni kesish ham yetarli bo'lmasdi, ey Sa'id."}], "full_uz": "Agar xo'jayining Vosiq seni buni aytayotganingni eshitsa, tilingni kesish ham yetarli bo'lmasdi, ey Sa'id.", "note": null},
{"num": 372, "time": "00:31:35,080 --> 00:31:36,600", "arabic": "أَعْرِفُ ذَلِكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Buni bilaman, xo'jayinim.", "note": null},
{"num": 374, "time": "00:31:37,660 --> 00:31:42,100", "arabic": "الْمُهِمُّ أَنْ تَضَعَهَا فِي يَدِهِ، لَا فِي يَدِ غَيْرِهِ، أَفَهِمْتَ؟", "segs": [{"ar": "الْمُهِمُّ أَنْ تَضَعَهَا فِي يَدِهِ،", "uz": "Muhimi, uni uning o'z qo'liga topshir,"}, {"ar": "لَا فِي يَدِ غَيْرِهِ، أَفَهِمْتَ؟", "uz": "boshqasining qo'liga emas, tushundingmi?"}], "full_uz": "Muhimi, uni uning o'z qo'liga topshir, boshqasining qo'liga emas, tushundingmi?", "note": null},
{"num": 376, "time": "00:31:42,100 --> 00:31:43,680", "arabic": "أَجَلْ يَا مَوْلَايَ، فَهِمْتُ.", "segs": null, "full_uz": "Ha, xo'jayinim, tushundim.", "note": null},
{"num": 377, "time": "00:31:43,680 --> 00:31:48,560", "arabic": "اذْهَبْ وَلَا تَعُدْ حَتَّى تُخْبِرَنِي بِمَا يَقُولُهُ لَكَ الْإِمَامُ.", "segs": null, "full_uz": "Bor, va Imom senga nima aytishini menga xabar bermaguncha qaytma.", "note": null},
{"num": 379, "time": "00:31:48,560 --> 00:31:49,580", "arabic": "بِإِذْنِ مَوْلَايَ.", "segs": null, "full_uz": "Xo'jayinimning ruxsati bilan.", "note": null},
{"num": 380, "time": "00:31:49,579 --> 00:32:33,779", "arabic": "أَخْبِرْ مَوْلَاكَ أَنَّ أَحْمَدَ بْنَ حَنْبَلٍ قَدْ غَفَرَ لِأَمِيرِ الْمُؤْمِنِينَ الْمُعْتَصِمِ مُنْذُ لَحْظَةِ خُرُوجِهِ مِنْ قَصْرِهِ، وَلَقَدْ جَعَلَهُ فِي حِلٍّ وَسَعَةٍ مِنْ أَوَّلِ يَوْمٍ إِكْرَامًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذْ كَانَ رَجُلًا مِنْ أَهْلِهِ، وَأَعْلِمْهُ أَنَّ أَحْمَدَ بْنَ حَنْبَلٍ يَدْعُو لَهُ بِالْخَيْرِ كَمَا أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "segs": [{"ar": "أَخْبِرْ مَوْلَاكَ أَنَّ أَحْمَدَ بْنَ حَنْبَلٍ قَدْ غَفَرَ لِأَمِيرِ الْمُؤْمِنِينَ الْمُعْتَصِمِ مُنْذُ لَحْظَةِ خُرُوجِهِ مِنْ قَصْرِهِ", "uz": "Xo'jayingga xabar ber: Ahmad ibn Hanbal mo'minlar amiri Mu'tasimni saroyidan chiqqan lahzasidayoq kechirgan"}, {"ar": "وَلَقَدْ جَعَلَهُ فِي حِلٍّ وَسَعَةٍ مِنْ أَوَّلِ يَوْمٍ إِكْرَامًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذْ كَانَ رَجُلًا مِنْ أَهْلِهِ", "uz": "birinchi kunidanoq, Rasulullohning oilasidan bo'lgani uchun, uni hurmat qilib halol va kechirilgan qildi"}, {"ar": "وَأَعْلِمْهُ أَنَّ أَحْمَدَ بْنَ حَنْبَلٍ يَدْعُو لَهُ بِالْخَيْرِ كَمَا أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "va unga bildirki, Ahmad ibn Hanbal Rasululloh buyurganidek unga yaxshilik tilab duo qiladi"}], "full_uz": "Xo'jayingga xabar ber: Ahmad ibn Hanbal mo'minlar amiri Mu'tasimni uning saroyidan chiqqan lahzasidayoq kechirgan, va uni birinchi kunidanoq, Rasululloh (sollallohu alayhi va sallam)ning oilasidan bo'lgani uchun, u zotni hurmat qilib, halol va kechirilgan qildi. Va unga bildirki, Ahmad ibn Hanbal Rasululloh (sav) buyurganidek unga yaxshilik tilab duo qiladi.", "note": null},
{"num": 387, "time": "00:32:33,779 --> 00:32:41,819", "arabic": "أَتَأْذَنُ لِي يَا إِمَامُ؟", "segs": null, "full_uz": "Ijozat berasizmi, Imom?", "note": null},
{"num": 388, "time": "00:32:41,819 --> 00:32:45,000", "arabic": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Assalomu alaykum va rahmatullah.", "note": null},
{"num": 389, "time": "00:32:45,000 --> 00:32:47,339", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullah.", "note": null},
{"num": 390, "time": "00:32:47,339 --> 00:33:09,000", "arabic": "أَيُرِيدُونَ مِنْكَ أَنْ تَغْفِرَ لِأَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Sizdan mo'minlar amirini kechirishingizni istashyaptimi?", "note": null},
{"num": 391, "time": "00:33:15,000 --> 00:33:28,000", "arabic": "يَا وَلَدِي، يَشْهَدُ اللَّهُ أَنَّنِي لَمْ أَحْمِلْ فِي قَلْبِي يَوْمًا غِلًّا لِمُسْلِمٍ، مَا الَّذِي يَنْفَعُنِي أَنْ يُعَذِّبَ اللَّهُ مُسْلِمًا بِسَبَبِي؟", "segs": [{"ar": "يَا وَلَدِي، يَشْهَدُ اللَّهُ أَنَّنِي لَمْ أَحْمِلْ فِي قَلْبِي يَوْمًا غِلًّا لِمُسْلِمٍ،", "uz": "O'g'lim, Alloh guvohki, men qalbimda hech qachon biror musulmonga adovat saqlamaganman,"}, {"ar": "مَا الَّذِي يَنْفَعُنِي أَنْ يُعَذِّبَ اللَّهُ مُسْلِمًا بِسَبَبِي؟", "uz": "mendan sabab Alloh biror musulmonni azoblasa, menga qanday foyda beradi?"}], "full_uz": "O'g'lim, Alloh guvohki, men qalbimda hech qachon biror musulmonga adovat saqlamaganman. Mendan sabab Alloh biror musulmonni azoblasa, menga qanday foyda beradi?", "note": null},
{"num": 393, "time": "00:33:31,140 --> 00:33:38,000", "arabic": "اللَّهُمَّ مَنْ كَانَ عَلَى رَأْيٍ يَظُنُّهُ حَقًّا وَهُوَ لَيْسَ كَذَلِكَ فَرُدَّهُ إِلَى الْحَقِّ رَدًّا جَمِيلًا.", "segs": [{"ar": "اللَّهُمَّ مَنْ كَانَ عَلَى رَأْيٍ يَظُنُّهُ حَقًّا", "uz": "Ey Alloh, kim haq deb o'ylagan,"}, {"ar": "وَهُوَ لَيْسَ كَذَلِكَ", "uz": "lekin aslida haq bo'lmagan bir fikrda bo'lsa,"}, {"ar": "فَرُدَّهُ إِلَى الْحَقِّ رَدًّا جَمِيلًا.", "uz": "uni chiroyli tarzda haqqa qaytar."}], "full_uz": "Ey Alloh, kim haq deb o'ylagan, lekin aslida haq bo'lmagan bir fikrda bo'lsa, uni chiroyli tarzda haqqa qaytar.", "note": null},
{"num": 394, "time": "00:33:38,859 --> 00:33:50,000", "arabic": "اللَّهُمَّ انْصُرِ الْمُسْلِمِينَ عَلَى أَعْدَائِهِمْ، وَوَفِّقْ عَبْدَكَ الْمُعْتَصِمَ وَوُلَاتَهُ بِمَا فِيهِ خَيْرُ الْبِلَادِ وَخَيْرُ الْعِبَادِ، يَا رَبَّ الْعَالَمِينَ.", "segs": [{"ar": "اللَّهُمَّ انْصُرِ الْمُسْلِمِينَ عَلَى أَعْدَائِهِمْ،", "uz": "Ey Alloh, musulmonlarni dushmanlariga qarshi qo'llab-quvvatla,"}, {"ar": "وَوَفِّقْ عَبْدَكَ الْمُعْتَصِمَ وَوُلَاتَهُ بِمَا فِيهِ خَيْرُ الْبِلَادِ وَخَيْرُ الْعِبَادِ،", "uz": "bandang Mu'tasim va uning noiblarini yurt va bandalar uchun foydali bo'lgan ishga muvaffaq qil,"}, {"ar": "يَا رَبَّ الْعَالَمِينَ.", "uz": "ey olamlarning Robbisi."}], "full_uz": "Ey Alloh, musulmonlarni dushmanlariga qarshi qo'llab-quvvatla, bandang Mu'tasim va uning noiblarini yurt va bandalar uchun foydali bo'lgan ishga muvaffaq qil, ey olamlarning Robbisi.", "note": null},
{"num": 398, "time": "00:34:44,000 --> 00:35:12,840", "arabic": "الْآنَ، اللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَانْصُرِ الْمُسْلِمِينَ، يَا قَوِيُّ يَا مَتِينُ.", "segs": [{"ar": "الْآنَ، اللَّهُمَّ أَعِزَّ الْإِسْلَامَ وَانْصُرِ الْمُسْلِمِينَ،", "uz": "Hozir — ey Alloh, Islomni aziz qil va musulmonlarga yordam ber,"}, {"ar": "يَا قَوِيُّ يَا مَتِينُ.", "uz": "ey Kuchli, ey Mustahkam Zot."}], "full_uz": "Hozir — ey Alloh, Islomni aziz qil va musulmonlarga yordam ber, ey Kuchli, ey Mustahkam Zot.", "note": null},
{"num": 401, "time": "00:35:12,840 --> 00:35:31,400", "arabic": "اللَّهُمَّ إِنْ كَانَ أَمِيرُ الْمُؤْمِنِينَ الْمُعْتَصِمُ قَدْ خَرَجَ إِعْلَاءً لِكَلِمَةِ اللَّهِ وَنُصْرَةً لِلْمَظْلُومِينَ، فَأَيِّدْهُ بِنَصْرِكَ، وَثَبِّتْ أَقْدَامَهُ، وَاهْزِمْ أَعْدَاءَهُ. اللَّهُمَّ آمِينَ.", "segs": [{"ar": "اللَّهُمَّ إِنْ كَانَ أَمِيرُ الْمُؤْمِنِينَ الْمُعْتَصِمُ قَدْ خَرَجَ إِعْلَاءً لِكَلِمَةِ اللَّهِ وَنُصْرَةً لِلْمَظْلُومِينَ،", "uz": "Ey Alloh, agar mo'minlar amiri Mu'tasim Sening kalimangni yuksaltirish va mazlumlarga yordam berish uchun chiqqan bo'lsa,"}, {"ar": "فَأَيِّدْهُ بِنَصْرِكَ، وَثَبِّتْ أَقْدَامَهُ،", "uz": "uni O'z nusrating bilan qo'llab-quvvatla, oyoqlarini mustahkam qil,"}, {"ar": "وَاهْزِمْ أَعْدَاءَهُ. اللَّهُمَّ آمِينَ.", "uz": "va dushmanlarini mag'lub et. Ey Alloh, omin."}], "full_uz": "Ey Alloh, agar mo'minlar amiri Mu'tasim Sening kalimangni yuksaltirish va mazlumlarga yordam berish uchun chiqqan bo'lsa, uni O'z nusrating bilan qo'llab-quvvatla, oyoqlarini mustahkam qil, va dushmanlarini mag'lub et. Ey Alloh, omin.", "note": null},
{"num": 407, "time": "00:35:31,400 --> 00:35:37,220", "arabic": "يَا رَبِّ.", "segs": null, "full_uz": "Ey Robbim.", "note": null},
{"num": 408, "time": "00:35:37,220 --> 00:35:50,640", "arabic": "أَيُّهَا الْإِخْوَةُ، إِنَّ الْأَخْبَارَ الَّتِي تَرِدُ مِنْ ثُغُورِ الشَّمَالِ تُبْهِجُ الْقَلْبَ، إِنَّ الْمُسْلِمِينَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى مِنَ النَّصْرِ إِنْ شَاءَ اللَّهُ.", "segs": [{"ar": "أَيُّهَا الْإِخْوَةُ،", "uz": "Ey birodarlar,"}, {"ar": "إِنَّ الْأَخْبَارَ الَّتِي تَرِدُ مِنْ ثُغُورِ الشَّمَالِ تُبْهِجُ الْقَلْبَ،", "uz": "shimoliy chegaralardan kelayotgan xabarlar qalbni quvontiryapti,"}, {"ar": "إِنَّ الْمُسْلِمِينَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى", "uz": "musulmonlar g'alabaga juda yaqin qolishdi,"}, {"ar": "مِنَ النَّصْرِ إِنْ شَاءَ اللَّهُ.", "uz": "inshaalloh."}], "full_uz": "Ey birodarlar, shimoliy chegaralardan kelayotgan xabarlar qalbni quvontiryapti, musulmonlar g'alabaga juda yaqin qolishdi, inshaalloh.", "note": null},
{"num": 411, "time": "00:35:50,640 --> 00:35:55,020", "arabic": "وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ، إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ.", "segs": [{"ar": "وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ،", "uz": "G'alaba faqat Alloh tomonidandir,"}, {"ar": "إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ.", "uz": "albatta Alloh qudratli va hikmatlidir."}], "full_uz": "G'alaba faqat Alloh tomonidandir, albatta Alloh qudratli va hikmatlidir.", "note": "Qur'on, Oli Imron surasi, 126-oyat va Anfol surasi, 10-oyatga ishora."},
{"num": 413, "time": "00:35:55,020 --> 00:36:01,540", "arabic": "قَدْ يَكُونُ الْمُعْتَصِمُ قَوِيًّا عَلَى الْكُفَّارِ كَأَبِيهِ هَارُونَ، لَكِنَّهُ سَرِيعٌ إِلَى ابْنِ الْعَمِّ يَجْلِدُ ظَهْرَهُ.", "segs": [{"ar": "قَدْ يَكُونُ الْمُعْتَصِمُ قَوِيًّا", "uz": "Mu'tasim otasi Horunga o'xshab"}, {"ar": "عَلَى الْكُفَّارِ كَأَبِيهِ هَارُونَ،", "uz": "kofirlarga qarshi kuchli bo'lishi mumkin,"}, {"ar": "لَكِنَّهُ سَرِيعٌ إِلَى ابْنِ الْعَمِّ يَجْلِدُ ظَهْرَهُ.", "uz": "lekin u amakivachchasining orqasini qamchilashga tez."}], "full_uz": "Mu'tasim otasi Horunga o'xshab kofirlarga qarshi kuchli bo'lishi mumkin, lekin u amakivachchasining orqasini qamchilashga tez.", "note": null},
{"num": 415, "time": "00:36:01,540 --> 00:36:13,179", "arabic": "أَلَمْ تَرَوْا أَنَّهُ شَدِيدٌ عَلَى أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ، مُفَارِقٌ لِعَقِيدَتِهِمْ، يَنْصُرُ أَهْلَ الْبِدَعِ وَالْأَهْوَاءِ؟ أَمْ أَنَّكُمْ نَسِيتُمْ ظُلْمَ الْمُعْتَصِمِ لِلْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ؟", "segs": [{"ar": "أَلَمْ تَرَوْا أَنَّهُ شَدِيدٌ عَلَى أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ، مُفَارِقٌ لِعَقِيدَتِهِمْ،", "uz": "Uning ahli sunna va jamoatga qattiq qo'l, ularning e'tiqodidan uzoq ekanini ko'rmadinglarmi,"}, {"ar": "يَنْصُرُ أَهْلَ الْبِدَعِ وَالْأَهْوَاءِ؟", "uz": "bid'at va havo-nafs ahliga yordam berayotganini?"}, {"ar": "أَمْ أَنَّكُمْ نَسِيتُمْ ظُلْمَ الْمُعْتَصِمِ لِلْإِمَامِ أَحْمَدَ بْنِ حَنْبَلٍ؟", "uz": "Yoki Mu'tasimning Imom Ahmad ibn Hanbalga qilgan zulmini unutdinglarmi?"}], "full_uz": "Uning ahli sunna va jamoatga qattiq qo'l, ularning e'tiqodidan uzoq, bid'at va havo-nafs ahliga yordam berayotganini ko'rmadinglarmi? Yoki Mu'tasimning Imom Ahmad ibn Hanbalga qilgan zulmini unutdinglarmi?", "note": null},
{"num": 419, "time": "00:36:13,179 --> 00:36:14,360", "arabic": "طَالِبٌ، يَا وَلَدِي.", "segs": null, "full_uz": "Tolib, o'g'lim.", "note": null},
{"num": 420, "time": "00:36:14,360 --> 00:36:23,360", "arabic": "إِنَّنَا مُطَالَبُونَ بِتَقْدِيمِ حُسْنِ الظَّنِّ بِالْمُسْلِمِينَ، خَاصَّتِهِمْ وَعَامَّتِهِمْ.", "segs": null, "full_uz": "Bizdan musulmonlarga, ular xoh xos, xoh omma bo'lsin, yaxshi gumon qilishimiz talab qilinadi.", "note": null},
{"num": 422, "time": "00:36:23,360 --> 00:36:28,219", "arabic": "وَنَحْنُ قَوْمُ إِنْصَافٍ وَعَدْلٍ، لَسْنَا كَغَيْرِنَا.", "segs": null, "full_uz": "Va biz insof va adolat ahlimiz, boshqalarga o'xshamaymiz.", "note": null},
{"num": 424, "time": "00:36:28,219 --> 00:36:43,960", "arabic": "وَلَعَلَّكَ تَذْكُرُ أَنَّ أَكْثَرَ أَهْلِ بَغْدَادَ خَرَجُوا لِنُصْرَةِ الْإِمَامِ أَحْمَدَ لَمَّا شَعَرُوا أَنَّ هُنَاكَ ظُلْمًا وَاقِعًا عَلَيْهِ مِنَ الْمُعْتَصِمِ بِيَدِ غَيْرِهِ مِمَّنْ حَوْلَهُ.", "segs": [{"ar": "وَلَعَلَّكَ تَذْكُرُ أَنَّ أَكْثَرَ أَهْلِ بَغْدَادَ خَرَجُوا لِنُصْرَةِ الْإِمَامِ أَحْمَدَ", "uz": "Balki eslarsan, Bag'dod ahlining ko'pi Imom Ahmadga yordam uchun chiqqan edi,"}, {"ar": "لَمَّا شَعَرُوا أَنَّ هُنَاكَ ظُلْمًا وَاقِعًا عَلَيْهِ مِنَ الْمُعْتَصِمِ", "uz": "Mu'tasim tomonidan unga zulm bo'layotganini his qilganlarida,"}, {"ar": "بِيَدِ غَيْرِهِ مِمَّنْ حَوْلَهُ.", "uz": "uning atrofidagilarning qo'li bilan."}], "full_uz": "Balki eslarsan, Bag'dod ahlining ko'pi Imom Ahmadga yordam uchun chiqqan edi, Mu'tasim tomonidan, uning atrofidagilarning qo'li bilan unga zulm bo'layotganini his qilganlarida.", "note": null},
{"num": 428, "time": "00:36:43,960 --> 00:36:53,480", "arabic": "لَكِنَّهُ لَمَّا رُفِعَ الظُّلْمُ، وَالْإِمَامُ أَحْمَدُ قَدْ عَفَا عَمَّنْ ظَلَمَهُ، فَمَا الدَّاعِي لِكَلَامِكَ هَذَا؟", "segs": [{"ar": "لَكِنَّهُ لَمَّا رُفِعَ الظُّلْمُ، وَالْإِمَامُ أَحْمَدُ قَدْ عَفَا عَمَّنْ ظَلَمَهُ،", "uz": "Lekin zulm ko'tarilgan va Imom Ahmad o'ziga zulm qilganlarni afv etgan ekan,"}, {"ar": "فَمَا الدَّاعِي لِكَلَامِكَ هَذَا؟", "uz": "seni bunday gapirishga nima undayapti?"}], "full_uz": "Lekin zulm ko'tarilgan va Imom Ahmad o'ziga zulm qilganlarni afv etgan ekan, seni bunday gapirishga nima undayapti?", "note": null},
{"num": 431, "time": "00:36:56,399 --> 00:37:03,339", "arabic": "نَحْنُ فِي جِهَادٍ لَا لَبْسَ فِيهِ يَا طَالِبُ، الْخُزَاعِيُّ عَلَى حَقٍّ.", "segs": [{"ar": "نَحْنُ فِي جِهَادٍ لَا لَبْسَ فِيهِ يَا طَالِبُ،", "uz": "Biz shubhasiz jihoddamiz, ey Tolib,"}, {"ar": "الْخُزَاعِيُّ عَلَى حَقٍّ.", "uz": "al-Xuzoiy haqdir."}], "full_uz": "Biz shubhasiz jihoddamiz, ey Tolib, al-Xuzoiy haqdir.", "note": null},
{"num": 433, "time": "00:37:03,340 --> 00:37:16,820", "arabic": "فَهَذِهِ صَفْحَةٌ طُوِيَتْ وَلَا يَفْتَحُهَا إِلَّا مُغْرِضٌ يَهْوَى الْفِتَنَ، أَنْ نَدَعَ قِتَالَ الْكَافِرِينَ الَّذِينَ يُحَارِبُونَنَا بِالسَّيْفِ وَالرُّمْحِ.", "segs": [{"ar": "فَهَذِهِ صَفْحَةٌ طُوِيَتْ", "uz": "Bu yopilgan sahifa,"}, {"ar": "وَلَا يَفْتَحُهَا إِلَّا مُغْرِضٌ يَهْوَى الْفِتَنَ،", "uz": "uni faqat fitnani yaxshi ko'radigan g'arazli kishi ochadi — biz esa qilich"}, {"ar": "أَنْ نَدَعَ قِتَالَ الْكَافِرِينَ الَّذِينَ يُحَارِبُونَنَا بِالسَّيْفِ وَالرُّمْحِ.", "uz": "va nayza bilan biz bilan urushayotgan kofirlar bilan jangni tashlab qo'ymasligimiz kerak."}], "full_uz": "Bu yopilgan sahifa, uni faqat fitnani yaxshi ko'radigan g'arazli kishi ochadi — biz esa qilich va nayza bilan biz bilan urushayotgan kofirlar bilan jangni tashlab qo'ymasligimiz kerak.", "note": null},
{"num": 435, "time": "00:37:16,820 --> 00:37:20,400", "arabic": "وَنَنْبُشَ مَاضِيًا قَدِ انْتَهَى.", "segs": null, "full_uz": "Va tugagan o'tmishni qayta kavlashimiz kerak emas.", "note": null},
{"num": 436, "time": "00:37:20,400 --> 00:37:23,660", "arabic": "يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Ey Ibn Siroj.", "note": null},
{"num": 437, "time": "00:37:23,660 --> 00:37:29,640", "arabic": "كَدَرُ جَمَاعَةٍ خَيْرٌ مِنْ صَفْوِ تَفَرُّقٍ.", "segs": null, "full_uz": "Jamoaning g'ubori bo'linishning tiniqligidan yaxshiroqdir.", "note": "\"كدر جماعة خير من صفو تفرق\" — birlikning noqisligi bo'linishning yaxshiligidan afzal ekanligi haqidagi arab maqoli."},
{"num": 438, "time": "00:37:29,639 --> 00:37:34,679", "arabic": "هَذِهِ مَسْأَلَةٌ قَدِيمَةٌ وَوَلَّى زَمَانُهَا.", "segs": null, "full_uz": "Bu eski masala, uning davri o'tib ketgan.", "note": null},
{"num": 439, "time": "00:37:34,679 --> 00:37:43,079", "arabic": "فَلْنَكُنْ عَادِلِينَ مَعَ أُولِي أَمْرِنَا، كَمَا طَلَبْنَاهُمْ أَنْ يَكُونُوا عَادِلِينَ بَيْنَنَا.", "segs": [{"ar": "فَلْنَكُنْ عَادِلِينَ مَعَ أُولِي أَمْرِنَا،", "uz": "Rahbarlarimizga adolatli bo'laylik,"}, {"ar": "كَمَا طَلَبْنَاهُمْ أَنْ يَكُونُوا عَادِلِينَ بَيْنَنَا.", "uz": "ular bizga adolatli bo'lishlarini talab qilganimizdek."}], "full_uz": "Rahbarlarimizga adolatli bo'laylik, ular bizga adolatli bo'lishlarini talab qilganimizdek.", "note": null},
{"num": 441, "time": "00:37:43,079 --> 00:37:53,639", "arabic": "هَلْ يَحْمِلُ إِخْوَتُنَا السِّلَاحَ عَلَى أَعْدَائِنَا، وَنَحْمِلُ نَحْنُ السَّيْفَ هُنَا عَلَى رِقَابِهِمْ؟", "segs": [{"ar": "هَلْ يَحْمِلُ إِخْوَتُنَا السِّلَاحَ عَلَى أَعْدَائِنَا،", "uz": "Birodarlarimiz dushmanlarimizga qarshi qurol ko'targani holda,"}, {"ar": "وَنَحْمِلُ نَحْنُ السَّيْفَ هُنَا عَلَى رِقَابِهِمْ؟", "uz": "biz shu yerda ularning bo'yniga qilich ko'tarsakmi?"}], "full_uz": "Birodarlarimiz dushmanlarimizga qarshi qurol ko'targani holda, biz shu yerda ularning bo'yniga qilich ko'tarsakmi?", "note": null},
{"num": 443, "time": "00:37:56,159 --> 00:38:00,779", "arabic": "إِنَّمَا سُكُوتُ الْمُعْتَصِمِ عَنْ هَذَا الْأَمْرِ كَالنَّارِ تَحْتَ الرَّمَادِ أَيُّهَا السَّادَةُ.", "segs": [{"ar": "إِنَّمَا سُكُوتُ الْمُعْتَصِمِ عَنْ هَذَا الْأَمْرِ", "uz": "Mu'tasimning bu masaladagi sukuti kul ostidagi olovga o'xshaydi,"}, {"ar": "كَالنَّارِ تَحْتَ الرَّمَادِ أَيُّهَا السَّادَةُ.", "uz": "ey janoblar."}], "full_uz": "Mu'tasimning bu masaladagi sukuti kul ostidagi olovga o'xshaydi, ey janoblar.", "note": null},
{"num": 445, "time": "00:38:00,779 --> 00:38:08,159", "arabic": "وَأَنْتُمْ تَعْلَمُونَ أَنَّ الْوَاثِقَ بْنَ الْمُعْتَصِمِ أَشَدُّ انْتِصَارًا لِلْمُعْتَزِلَةِ وَأَشَدُّ إِعْجَابًا بِأَفْكَارِهِمْ مِنَ الْمَأْمُونِ نَفْسِهِ.", "segs": [{"ar": "وَأَنْتُمْ تَعْلَمُونَ أَنَّ الْوَاثِقَ", "uz": "Va bilasizki,"}, {"ar": "بْنَ الْمُعْتَصِمِ أَشَدُّ انْتِصَارًا لِلْمُعْتَزِلَةِ", "uz": "Mu'tasimning o'g'li Vosiq Mu'tazilaga Ma'munning o'zidan ham"}, {"ar": "وَأَشَدُّ إِعْجَابًا بِأَفْكَارِهِمْ مِنَ الْمَأْمُونِ نَفْسِهِ.", "uz": "ko'proq yordamchi va ularning fikrlariga ko'proq maftundir."}], "full_uz": "Va bilasizki, Mu'tasimning o'g'li Vosiq Mu'tazilaga Ma'munning o'zidan ham ko'proq yordamchi va ularning fikrlariga ko'proq maftundir.", "note": null},
{"num": 448, "time": "00:38:08,159 --> 00:38:11,719", "arabic": "فَمَاذَا إِنْ مَاتَ الْمُعْتَصِمُ غَدًا وَصِرْنَا فِي قَبْضَةِ الْوَاثِقِ؟", "segs": null, "full_uz": "Xo'sh, agar Mu'tasim ertaga vafot etib, biz Vosiqning qo'liga tushib qolsak, nima bo'ladi?", "note": null},
{"num": 450, "time": "00:38:14,279 --> 00:38:18,199", "arabic": "حِينَهَا...", "segs": null, "full_uz": "O'shanda...", "note": null},
{"num": 451, "time": "00:38:18,199 --> 00:38:21,079", "arabic": "لِكُلِّ حَادِثٍ حَدِيثٌ.", "segs": null, "full_uz": "Har bir voqeaning o'ziga yarasha gapi bor.", "note": "\"لكل حادث حديث\" — har bir yangi vaziyat o'z vaqtida hal qilinishi kerakligi haqidagi arab maqoli."},
{"num": 452, "time": "00:38:21,079 --> 00:38:31,559", "arabic": "وَمَا دُمْنَا نَعْمَلُ لِلَّهِ، فَاللَّهُ سَيُهَيِّئُ لَنَا مِنْ أَمْرِنَا رُشْدًا، كَانَ الْمُعْتَصِمُ أَوْ كَانَ غَيْرَهُ.", "segs": [{"ar": "وَمَا دُمْنَا نَعْمَلُ لِلَّهِ،", "uz": "Alloh uchun ish qilar ekanmiz,"}, {"ar": "فَاللَّهُ سَيُهَيِّئُ لَنَا مِنْ أَمْرِنَا رُشْدًا،", "uz": "Alloh bizga ishimizda to'g'ri yo'lni tayyorlab beradi,"}, {"ar": "كَانَ الْمُعْتَصِمُ أَوْ كَانَ غَيْرَهُ.", "uz": "xoh Mu'tasim bo'lsin, xoh boshqasi."}], "full_uz": "Alloh uchun ish qilar ekanmiz, Alloh bizga ishimizda to'g'ri yo'lni tayyorlab beradi, xoh Mu'tasim bo'lsin, xoh boshqasi.", "note": null},
{"num": 455, "time": "00:38:31,559 --> 00:38:35,480", "arabic": "وَلَكِنْ يَا شَيْخَنَا أَنْتَ تَعْلَمُ سُوءَ مَذْهَبِ الْوَاثِقِ وَاعْتِقَادِهِ.", "segs": null, "full_uz": "Lekin, shayximiz, siz Vosiqning mazhabi va e'tiqodining yomonligini bilasiz.", "note": null},
{"num": 456, "time": "00:38:35,480 --> 00:38:46,300", "arabic": "لَا يَهُمُّنِي مَذْهَبُ الْوَاثِقِ مَا دَامَ يَحْتَفِظُ بِهِ لِنَفْسِهِ، وَلَا يُعْلِنُهُ عَلَى الْمَلَإِ، وَلَا يُجْبِرُ غَيْرَهُ بِاعْتِقَادِهِ.", "segs": [{"ar": "لَا يَهُمُّنِي مَذْهَبُ الْوَاثِقِ مَا دَامَ يَحْتَفِظُ بِهِ لِنَفْسِهِ،", "uz": "Vosiqning mazhabi o'zi uchun saqlab qolsa, meni qiziqtirmaydi,"}, {"ar": "وَلَا يُعْلِنُهُ عَلَى الْمَلَإِ،", "uz": "ommaga e'lon qilmasa,"}, {"ar": "وَلَا يُجْبِرُ غَيْرَهُ بِاعْتِقَادِهِ.", "uz": "va boshqasini o'z e'tiqodiga majburlamasa."}], "full_uz": "Vosiqning mazhabi o'zi uchun saqlab, ommaga e'lon qilmasa va boshqasini o'z e'tiqodiga majburlamasa, meni qiziqtirmaydi.", "note": null},
{"num": 460, "time": "00:38:46,300 --> 00:38:47,099", "arabic": "فَإِنْ فَعَلَ...", "segs": null, "full_uz": "Agar shunday qilsa...", "note": null},
{"num": 461, "time": "00:38:47,099 --> 00:38:52,579", "arabic": "قُلْتُ لَكَ مِنْ قَبْلُ، لِكُلِّ حَادِثٍ حَدِيثٌ.", "segs": null, "full_uz": "Senga oldin ham aytgan edim, har bir voqeaning o'ziga yarasha gapi bor.", "note": null}
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}